function affordable(o){return state.money>=(o.money||0)&&state.grain>=(o.grain||0);}
function chooseEvent(i){activeEventChoice=i;const el=$('#decision');if(el)el.outerHTML=decisionView();}
function chooseActor(id){if(state.events[0])state.events[0].actor=Number(id);save();}
function resolveEvent(expected){const e=state.events[0];if(!e||e.id!==expected||state.ended||activeEventChoice==null)return;const data=eventData(e),o=data?.choices[activeEventChoice];if(!o||!affordable(o))return toast('家里的储备还不够，可以选择另一种处理方式。');
 if(data.actorSelectable&&o.action!=='keep'&&!adults().length)return toast('这件事需要一位成年族人来办，孩子长大后仍可继续。');
 state.money-=o.money||0;state.grain-=o.grain||0;const effects=[];if(o.money)effects.push('银钱 −'+o.money+' 两');if(o.grain)effects.push('存粮 −'+o.grain+' 石');let body=o.label+'。';const m=get(e.target);
 if(e.type.startsWith('relic')){const r=own(e.relic);if(!r)return;r.history.push({year:state.elapsed,text:o.label});
 if(e.type==='relicStart'){if(o.action==='keep'){r.phase=0;body='物件被仔细收好。你可以从「传家旧物」里重新展开这条线索。';r.deferred=true;}else{r.phase=1;r.due=state.elapsed+(o.action==='slow'?2:1);r.actor=adults().some(x=>x.id===e.actor)?e.actor:(get(r.custodian)?.alive&&get(r.custodian).age>=18?r.custodian:adults()[0].id);r.route=o.action;body=get(r.actor).name+'接下了这件事。原有主业保持不变，预计第 '+(r.due+1)+' 年得到后续。';effects.push('调查进行中');personRecord(get(r.actor),'开始调查「'+relicDef(r.id).name+'」留下的线索。');}}
 else{r.phase=2;r.due=null;state.flags[r.id+'Complete']=true;const actor=get(r.actor)?.alive?get(r.actor):adults()[0];
 if(r.id==='ruler'&&o.action==='complete'){if(actor){actor.skill=clamp(actor.skill+6,0,100);effects.push(actor.name+'手艺 +6');}unlockRelic('plan','修复了老木尺指向的营造图');state.flags.rulerRestored=true;body='图纸被重新抄好，木尺也留在家里。这段手艺有了可供后人追寻的来处。';}else if(r.id==='ruler'){state.reputation+=6;body='旧图交给了当地的匠人，这份手艺会以另一种方式留下。';}
 if(r.id==='book'&&o.action==='complete'){unlockRelic('newbook','找回旧谱里被遗漏的亲族，重修记载');state.reputation+=5;state.flags.bookRestored=true;body='那个名字重新写回家谱。后人可以知道，分开生活不等于从未属于这个家。';}
 if(r.id==='letter'&&o.action==='complete'){unlockRelic('jade','把旧家书送到故人后辈手中，完成了前人的约定');state.reputation+=6;state.flags.promiseKept=true;body='对方送来半枚玉佩，作为这次相逢的见证。它成为以后可选的新开局信物，本局家书的故事已完成。';}else if(r.id==='letter')state.reputation+=3;
 if(r.id==='plan'){state.money+=40;state.reputation+=6;state.flags.bridge=true;effects.push('银钱 +40 两','声望 +6');}
 if(r.id==='newbook'){addRelative('reunion');effects.push('成年旁支 +1');}
 if(r.id==='jade'){state.reputation+=8;effects.push('声望 +8');}
 if(r.id==='notes'){state.reputation+=12;state.flags.publicNotes=true;effects.push('声望 +12');}
 r.history.push({year:state.elapsed,text:body});if(actor)personRecord(actor,'完成了「'+relicDef(r.id).name+'」的这段故事。');}}
 else if(o.action==='aid'){state.metrics.aid++;state.reputation+=6+(state.config.tie==='neighbor'?2:0);body='东西交到了邻人手里。家里确实付出过的这一回，会留在乡里的记忆中。';effects.push('记录援助 +1');}
 else if(o.action==='neighbor'){state.reputation+=3;body='一顿饭，让彼此知道了名字。';}
 else if(o.action==='repair'){living().forEach(x=>x.health=clamp(x.health+3,0,100));effects.push('全家体魄 +3');body='雨再来时，屋里终于不用放盆了。';}
 else if(o.action==='books'&&m?.alive){m.learn=clamp(m.learn+6,0,100);personRecord(m,'家里添置纸笔，支持继续求学。');effects.push(m.name+'学识 +6');}
 else if(o.action==='graduate'&&m?.alive&&candidateHasJob(m,e.job)){setMemberJob(m,e.job);body=m.name+'开始'+JOBS[e.job].name+'，下一次年度结算生效。';}
 else if(o.action==='medicalFind'){if(!own('notes'))state.relics.push({id:'notes',custodian:m?.alive?m.id:state.leader,status:'owned',phase:0,due:null,history:[{year:state.elapsed,text:'在行医的积累中，得到一份批注医案。'}]});unlockRelic('notes','累计行医六人年，并把一位在世医者培养到医术 55');body='医案交给了家里。它可以在本局继续研究，也成为未来开局的新选择。';}
 state.reputation=clamp(state.reputation,0,100);record(e.type.startsWith('relic')?'信物':'决定',data.title,body,effects);state.events.shift();activeEventChoice=null;state.lastDecision={title:data.title,body,effects};save();render();toast(store.profile.unlocked.length>3&&e.type==='relicFinish'?'后续已写进年鉴，可到信物藏阁查看解锁。':'决定已经记下，家里的日子继续。');}
function skillGain(m,j){let gain=j.gain||0;if(!gain)return 0;const c=state.config,p=by(PLACES,state.place);if(['study','apprentice','medical','train'].includes(m.job)){gain+=TALENTS[m.talent-1].gain;if(m.focus===j.stat)gain+=2;}if(m.job==='study'){gain+=(c.origin==='scholar'?2:0)+(c.habit==='education'?1:0)+(c.tie==='teacher'?1:0)+(p.study||0);}if(['craft','apprentice'].includes(m.job)&&c.origin==='artisan')gain++;if(m.job==='apprentice'&&own('ruler'))gain++;if(m.job==='medical'){if(c.tie==='healer')gain++;if(own('notes'))gain+=2;}if(m.job==='train'&&c.origin==='military')gain+=2;return Math.max(1,gain);}
function handovers(){return state.leaders.filter((l,i)=>i<state.leaders.length-1&&l.end!=null&&l.end-l.start>=1).length;}
function jobTotal(k){return state.members.reduce((s,m)=>s+(m.jobYears[k]||0),0);}
function jobGenerations(k,min=2){return new Set(state.members.filter(m=>(m.jobYears[k]||0)>=min).map(m=>m.gen)).size;}
function setMemberJob(m,k){const old=m.job;m.job=k;if((m.jobYears.guard||0)>=3&&['home','farm','rest'].includes(k))m.hadHomeAfterGuard=true;personRecord(m,'从'+JOBS[old].name+'改为'+JOBS[k].name+'。');record('安排',m.name+'有了新的安排',`你让${m.name}从${JOBS[old].name}改为${JOBS[k].name}。没有改变配偶、亲属关系或已经发生的经历。`,['下次年度结算生效']);}
function advanceYear(){if(state.ended)return showConclusion();if(state.events.length){page='overview';render();$('#decision')?.scrollIntoView({block:'center',behavior:'smooth'});return toast('先给眼前的家事一个答复。');}if((!get(state.leader)?.alive)&&adults().length)return openLeader();
 const b=estimate(state),beforeMoney=state.money,beforeGrain=state.grain,liveBefore=living().slice(),from=state.elapsed;state.elapsed++;state.lastDecision=null;state.money+=b.rawMoney;state.grain+=b.grainNet;let shortage=false,foodPurchased=0;
 if(state.money<0&&state.grain>0){const sell=Math.min(Math.floor(state.grain),Math.ceil(-state.money/Math.max(1,b.foodPrice-1)));state.grain-=sell;state.money+=sell*Math.max(1,b.foodPrice-1);record('生计','卖出一些粮，接上开支',`银钱不足，家里卖出${sell}石粮。不是新增收入，而是把已有储备换成了银钱。`,['存粮 −'+sell]);}
 if(state.grain<0){foodPurchased=Math.min(-state.grain,Math.floor(Math.max(0,state.money)/b.foodPrice));state.money-=foodPurchased*b.foodPrice;state.grain+=foodPurchased;if(foodPurchased)record('生计','从市集买回口粮',`这一年自产不足，花${foodPurchased*b.foodPrice}两买回${foodPurchased}石粮。`,[]);}
 if(state.money<0||state.grain<0){shortage=true;state.metrics.hardship++;state.money=Math.max(0,state.money);state.grain=Math.max(0,state.grain);liveBefore.forEach(m=>m.health-=12);record('困境','日子紧了，先把生计接上','储备不足，大家省着过日子。族长仍可换，生计仍能调整；这不是家族终局。',['全家体魄 −12']);}
 state.metrics.stable=shortage?0:state.metrics.stable+1;state.metrics.foodYears=shortage?0:state.metrics.foodYears+1;if(state.metrics.hardship&&state.metrics.stable>=3)state.metrics.recovered=true;
 const hasCarer=liveBefore.some(m=>m.job==='home'),home=state.home;let deaths=0;
 for(const m of liveBefore){const j=JOBS[m.job];m.jobYears[m.job]=(m.jobYears[m.job]||0)+1;if(j.stat)m[j.stat]=clamp(m[j.stat]+skillGain(m,j),0,100);m.age++;if(hasCarer)m.health++;if(m.job==='rest')m.health+=5+(state.config.habit==='care'?2:0)+(home==='courtyard'?1:home==='estate'?2:0);if(m.age>=55)m.health-=m.age>=70?5:2;else if(m.job==='guard')m.health-=2;m.health=clamp(m.health,0,100);if(m.job==='official')state.reputation++;
 if(m.age===18){personRecord(m,'成年，可以接受新的谋生安排，也可以成为族长候选。');record('成长',m.name+'成年了','这个人仍有自己的人生；是否接手家里的事情，由你决定。',['可任族长']);}
 if(m.job==='play'&&m.age>=12){m.job='rest';record('成长',m.name+'渐渐长大','暂时继续在家休息，未自动增加学费。可以从人物页选择读书或学艺。',[]);}
 if(m.health<=0||m.age>=m.lifespan){m.alive=false;m.deathYear=state.elapsed;deaths++;personRecord(m,'在这一年离世，享年 '+m.age+' 岁。');record('离别',m.name+'的这一生，写完了','家人把留下来的东西仔细收好。这个人的经历会一直保留在家谱中。',[]);if(state.leader===m.id){state.leaders.at(-1).end=state.elapsed;state.leader=null;}state.relics.filter(r=>r.custodian===m.id&&r.status!=='sold').forEach(r=>{r.custodian=null;r.history.push({year:state.elapsed,text:'保管人离世，物件收回家中，等待重新托付。'});});}
 }
 record('岁计','第'+(from+1)+'年的家计',`生产所得 ${b.income} 两，求学学艺 ${b.training} 两，日常开支 ${b.upkeep} 两。粮食产出 ${b.grainEarn} 石，日常吃用 ${b.eat} 石。`,['银钱 '+signed(state.money-beforeMoney)+' 两','存粮 '+signed(state.grain-beforeGrain)+' 石']);
 // A generation continues through living people, not a particular leader or surname line.
 if(!living().length){state.lastSummary={money:state.money-beforeMoney,grain:state.grain-beforeGrain,deaths};finishRun('last');return;}
 for(const m of living()){let graduation=null;if(m.job==='apprentice'&&m.skill>=35&&m.age>=18)graduation='craft';if(m.job==='medical'&&m.medicine>=40&&m.age>=18)graduation='doctor';if(m.job==='train'&&m.martial>=35&&m.age>=18)graduation='guard';if(graduation&&!m['offered_'+graduation]){m['offered_'+graduation]=true;addEvent('graduate-'+m.id+'-'+graduation,'graduate',{target:m.id,job:graduation});}}
 // Every specific relic owns its follow-up. A sold relic cannot deliver a late reward.
 state.relics.forEach(r=>{if(r.phase===1)queueRelic(r);});
 if(state.elapsed>=6&&state.elapsed-state.eraSince>=5&&rnd()<.22){const candidates=state.era==='unrest'?['rebuild']:state.era==='rebuild'?['peace','strain']:state.era==='peace'?['strain']:['peace','unrest'];const old=by(ERA,state.era);state.era=candidates[Math.floor(rnd()*candidates.length)];state.eraSince=state.elapsed;record('世道',old.name+'，渐渐翻过一页','乡里带来的消息变了，日常物价与谋生环境也在改变。如今是「'+by(ERA,state.era).name+'」。',[by(ERA,state.era).effect]);}
 for(const mom of living().filter(m=>m.sex==='女'&&m.age>=21&&m.age<=39&&m.spouse&&m.birthPlan)){const dad=get(mom.spouse);if(!dad?.alive||dad.sex!=='男'||!dad.birthPlan||dad.age<21||dad.age>60)continue;const count=state.members.filter(x=>x.parents.includes(mom.id)).length;if(count<3&&state.elapsed-mom.lastBirth>=4&&state.money>=16&&rnd()<.27){addBaby(mom,dad);break;}}
 if(!state.flags.notesOffered&&jobTotal('doctor')>=6&&living().some(m=>m.medicine>=55)){state.flags.notesOffered=true;addEvent('medical-find','medicalFind',{target:living().find(m=>m.medicine>=55).id});}
 if(state.elapsed%4===0)addEvent('aid-'+state.elapsed,'aid');else if(state.elapsed%7===0)addEvent('roof-'+state.elapsed,'roof');else if(state.elapsed%5===0){const c=living().find(m=>m.job==='study'&&m.age<18);if(c)addEvent('school-'+state.elapsed,'school',{target:c.id});}
 state.reputation=clamp(state.reputation+(state.config.origin==='gentry'?1:0),0,100);state.lastSummary={money:state.money-beforeMoney,grain:state.grain-beforeGrain,deaths};activeEventChoice=null;save();render();window.scrollTo(0,0);if(!get(state.leader)?.alive&&adults().length)openLeader();else toast('来到第 '+(state.elapsed+1)+' 年。'+(state.events.length?'有些事情已经有了后文。':'每个人都按原来的安排继续生活。'));}
function newGameMember(o){const id=state.nextId++;return {...rawPerson({id,name:state.family+'知禾',age:22,talent:2,experience:'basic',job:'farm'}),learn:25,skill:25,medicine:0,trade:10,martial:10,gen:1,alive:true,health:92,jobYears:{},bio:[],examPassed:false,deathYear:null,birthPlan:true,lastBirth:-5,lifespan:79+Math.floor(rnd()*13),...o,id};}
function addBaby(mom,dad){const suffix=['知禾','予安','明川','小满','望舒','怀青','景宁','知秋'][state.nextId%8];let name=state.family+suffix;if(state.members.some(m=>m.name===name))name+=String(state.nextId);const child=newGameMember({name,sex:rnd()<.5?'女':'男',age:0,parents:[mom.id,dad.id],gen:Math.max(mom.gen,dad.gen)+1,talent:1+Math.floor(rnd()*4),experience:'none',job:'play',learn:0,skill:0,trade:0,martial:0,medicine:0,spouse:null});child.bio=[{year:state.elapsed,text:'出生在这个家里，家谱添上新的一行。'}];state.members.push(child);mom.lastBirth=state.elapsed;dad.lastBirth=state.elapsed;personRecord(mom,name+'出生。');personRecord(dad,name+'出生。');record('新生','家里多了一个孩子：'+name,mom.name+'与'+dad.name+'迎来了下一代。孩子独立入谱，成长后可单独安排人生。',['人口 +1']);}
function addRelative(kind){const child=kind==='adopt';const l=child?(adults().find(m=>m.age>=24)||get(state.leader)||living()[0]):(get(state.leader)||living()[0]);const m=newGameMember({name:state.family+(child?'念安':'怀远')+state.nextId,age:child?6:22,sex:rnd()<.5?'女':'男',parents:child?[l.id]:[],gen:child?l.gen+1:Math.max(1,l.gen),job:child?'study':'farm',learn:child?5:25,skill:child?0:25,role:child?'收养的孩子':'归来的成年旁支',originGen:child?null:Math.max(1,l.gen)});m.bio=[{year:state.elapsed,text:child?'在成年家人的照料下加入家族。':'循着旧谱回到家里，成为可以单独安排的成员。'}];state.members.push(m);if(child)state.metrics.adoptions++;record(child?'收养':'团聚',m.name+'加入这个家','从此，家谱中多了一段独立的人生。',['人口 +1']);return m;}
const ENDINGS=[
 {id:'peaceful',title:'炊烟未断',category:'安居与生计',desc:'不曾显赫，却把安稳的日子接过了两任人手。',epilogue:'没有哪一年值得写进天下的大事记。但厨房的火始终没有熄过，这本家谱记得每一顿安稳的饭。',criteria:()=>[['实际经营十年',state.elapsed,10,'年'],['连续五年基本生活充足',state.metrics.stable,5,'年'],['完成一次真实族长交接',handovers(),1,'次']]},
 {id:'scholar',title:'书香传家',category:'求学与文化',desc:'不是一个人读过书，而是两代人都能把书教给别人。',epilogue:'最初只有一盏灯。后来，孩子们带着书出门，另一些孩子又循着灯火回来。这个家留住的，是愿意把知识交给后来人的心意。',criteria:()=>[['两代族人各教书至少两年',jobGenerations('teach',2),2,'代'],['现有积蓄达到二百两',state.money,200,'两'],['完成一次真实交接',handovers(),1,'次']]},
 {id:'merchant',title:'商脉长存',category:'财富与产业',desc:'前人打开一条路，后人认真接过了账册。',epilogue:'账本不再只记一家铺子的出入，也记着两代人的脚步。生意经历过难处，又被另一个人稳稳接了下去。',criteria:()=>[['两代族人各经商至少三年',jobGenerations('trade',3),2,'代'],['积蓄三百两',state.money,300,'两'],['完成一次真实交接',handovers(),1,'次']]},
 {id:'craft',title:'百年手艺',category:'医术与匠艺',desc:'尺与刨子在不同的人手里，仍然做出可靠的东西。',epilogue:'作坊的门换过几回，墙角的工具却一直有人使用。一双手老去，另一双手接过来，本事便没有离开这个家。',criteria:()=>[['两代族人各做手艺至少三年',jobGenerations('craft',3),2,'代'],['拥有正在经营的木工作坊',state.workshop&&living().some(m=>m.job==='craft')?1:0,1,'项'],['完成一次真实交接',handovers(),1,'次']]},
 {id:'medical',title:'杏林人家',category:'医术与匠艺',desc:'药箱不只传给后人，看人的耐心也一起留下。',epilogue:'药柜上的字是上一代写的，柜前的人已经换了。乡人仍愿意来敲门，知道这里有人会认真听完一句话。',criteria:()=>[['两代族人各行医至少两年',jobGenerations('doctor',2),2,'代'],['本局实际行医累计十二人年',jobTotal('doctor'),12,'人年'],['完成一次真实交接',handovers(),1,'次']]},
 {id:'grain',title:'四时有余',category:'安居与生计',desc:'过冬不必再借粮，孩子也不必先说自己不饿。',epilogue:'粮仓没有写上谁的功劳。它只安静地立在那里，让家里的人知道，下一季还有余地。',criteria:()=>[['实际经营十五年',state.elapsed,15,'年'],['连续十年基本生活充足',state.metrics.foodYears,10,'年'],['当前存粮八十石',state.grain,80,'石']]},
 {id:'community',title:'一村归心',category:'安居与生计',desc:'几次真正伸出去的手，让这个姓氏有了不同的分量。',epilogue:'乡里有事，总有人先来敲这扇门。这家人没有命令过谁，却被许多人当成可以依靠的邻人。',criteria:()=>[['实际经营十二年',state.elapsed,12,'年'],['实际援助邻里至少三次',state.metrics.aid,3,'次'],['乡里声望达到七十',state.reputation,70,'']]},
 {id:'migration',title:'异乡生根',category:'迁徙与远行',desc:'不是忘了来处，而是在新的地方把家续了下去。',epilogue:'最初来时，这里的街名都陌生。后来有人出生、有人老去，孩子终于自然地把这片地方叫作家。',criteria:()=>[['实际完成一次迁居',state.metrics.migrations,1,'次'],['最近一次迁居后生活八年',state.metrics.migrations?state.elapsed-state.metrics.lastMove:0,8,'年'],['连续五年生活充足',state.metrics.stable,5,'年']]},
 {id:'return',title:'归来有灯',category:'亲族与传承',desc:'走过远路的人卸下行装，家里仍有自己的位置。',epilogue:'刀与行囊被收进箱底。这个人不再赶着出门，开始听清院子里孩子的声音。留下来，也是人生的一种选择。',criteria:()=>[['有一位曾护卫三年并返家生活的在世族人',living().some(m=>m.hadHomeAfterGuard&&['rest','farm','home'].includes(m.job))?1:0,1,'人'],['实际经营八年',state.elapsed,8,'年'],['完成一次真实交接',handovers(),1,'次']]},
 {id:'promise',title:'迟来的家书',category:'信物与秘史',desc:'前人的一句答应，终于由后来的人认真完成。',epilogue:'信到的时候，最初等信的人已经不在。但他的后人知道，世上还有一家人，愿意替过去的一句话走这么远。',criteria:()=>[['完成家书并履行旧约',state.flags.promiseKept?1:0,1,'项'],['实际经营六年',state.elapsed,6,'年'],['连续三年生活充足',state.metrics.stable,3,'年']]},
 {id:'ruler',title:'木尺新纹',category:'信物与秘史',desc:'同一把木尺，量过前人的屋，也量过后人的路。',epilogue:'尺背的刻痕被辨认出来，图纸上又添了新的批注。以后有人拿起它，会知道本事不是突然落在自己手里的。',criteria:()=>[['由本局寻访修复旧图',state.flags.rulerRestored?1:0,1,'项'],['本局手艺谋生累计八人年',jobTotal('craft'),8,'人年'],['完成一次真实族长交接',handovers(),1,'次']]},
 {id:'reunion',title:'家谱再续',category:'亲族与传承',desc:'没有谁应该因为一段旧事，从家族的记忆里消失。',epilogue:'折起的那页被展开了。家谱不再只记住留下来的人，也认真记住曾经离开、后来又被想起的人。',criteria:()=>[['本局查明旧谱并重修记载',state.flags.bookRestored?1:0,1,'项'],['实际经营六年',state.elapsed,6,'年'],['完成一次真实交接',handovers(),1,'次']]},
 {id:'last',title:'家谱落笔',category:'复兴与灾变',desc:'直到最后一位家人也离开，这一局才自然写到结尾。',epilogue:'屋里的灯最终熄了。但那些被认真安排过、被彼此记住过的日子，并不会因此变成没有发生。',auto:true,criteria:()=>[['全部在世成员归零',living().length===0?1:0,1,'项']]}
];
function readyEndings(){return ENDINGS.filter(e=>!e.auto&&e.criteria().every(c=>c[1]>=c[2]));}
function endingBy(id){return ENDINGS.find(e=>e.id===id);}
function finishRun(id){if(state.ended)return;const e=endingBy(id);if(!e||(!e.auto&&!e.criteria().every(c=>c[1]>=c[2])))return;state.ended={id,title:e.title,year:state.elapsed,snapshot:{criteria:e.criteria(),money:state.money,grain:state.grain,people:state.members.length,leaders:state.leaders.length},qualified:readyEndings().map(g=>g.id)};state.events=[];if(!store.profile.endings.some(x=>x.runId===state.runId))store.profile.endings.push({id,title:e.title,family:state.family,year:state.elapsed,runId:state.runId});record('终章',e.title,e.epilogue,[]);save();render();showConclusion();}


const STEP_NAMES=[['世道与来处','时代、地区、来历'],['家中这些人','人数、资质、本领'],['安身的家底','资产、家风、人情'],['随身的旧物','信物与解锁'],['落笔之前','确认这一家的开头']];
function tag(t,cls=''){return `<span class="tag ${cls}">${esc(t)}</span>`;}
function sectionTitle(title,sub=''){return `<div class="section-title"><h2>${esc(title)}</h2><span>${esc(sub)}</span></div>`;}
function pageHead(kicker,title,sub='',right=''){return `<div class="page-head"><div><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div>${right}</div>`;}
function worldHeader(active='setup'){return `<header class="v3-top"><div class="v3-brand"><div class="seal">家</div><div><div class="brand-name">家业</div><div class="brand-caption">一部由你续写的家史</div></div></div><div class="v3-top-actions"><span class="prototype-tag">V4 · 凡世王朝</span><button class="header-tab ${active==='setup'?'active':''}" onclick="showSetup()">创建家族</button><button class="header-tab ${active==='collection'?'active':''}" onclick="showCollection()">信物藏阁<span class="header-count">${store.profile.unlocked.length} / ${RELICS.length}</span></button><button class="header-tab world-link ${active==='world'?'active':''}" onclick="showWorld()">凡世一览</button>${state?`<button class="btn small" onclick="returnGame()">${state.ended?'翻阅上局':'继续上次'} →</button>`:''}</div></header>`;}
function render(){document.body.className=screen==='setup'?'setup-mode':screen==='game'?'game-mode':'collection-mode';const root=$('#app');root.innerHTML=screen==='setup'?setupView():screen==='game'?gameView():screen==='collection'?collectionView():worldView();updateStorageNote();}
function updateStorageNote(){document.querySelectorAll('[data-save]').forEach(el=>{el.textContent=storageOK?'进度保存在当前浏览器':(storageMessage||'临时存档，请及时导出');});}
function toast(text){clearTimeout(toastTimer);const e=$('#toast');e.textContent=text;e.classList.add('visible');toastTimer=setTimeout(()=>e.classList.remove('visible'),3800);}
function renderBudget(){const total=totalPoints(),groups=pointGroups(),remain=round(LIMIT-total);let economy;try{economy=draftEstimate();}catch(e){economy=null;}const leader=draft.members.find(m=>m.id===draft.leader);return `<section class="budget-panel ${total>LIMIT?'budget-over':''}"><div class="budget-top"><span>开局点数</span>${tag(total>LIMIT?'超出预算':'自由配点',total>LIMIT?'red':'outline')}</div><div class="budget-number">${total}<small>/ ${LIMIT}</small></div><div class="budget-caption"><span class="remaining">${total>LIMIT?'超出 '+round(total-LIMIT)+' 点，请自行调整。':'还可使用 '+remain+' 点。'}</span><br>只限制总分，不限每一类投入。</div><div class="budget-segments" aria-label="已使用 ${total} 点">${groups.map(g=>`<span style="width:${g.value}%;background:${g.color}"></span>`).join('')}</div><div class="budget-totals">${groups.map(g=>`<div class="between"><button onclick="goStep(${g.step})"><i class="budget-dot" style="background:${g.color}"></i>${g.name}</button><span>${g.value}</span></div>`).join('')}</div><div class="budget-rule">想要更好的来历，还是更多的家人？<br>怎么取舍，由你决定。<div style="margin-top:10px"><button class="text-btn" onclick="openPriceDetail()">逐项查看点数明细 ↗</button></div></div></section><section class="family-preview"><span class="small muted">这本家谱的第一页</span><h3>${esc(draft.family||'未名')}氏家族</h3><p>${by(ORIGINS,draft.origin).name}出身，在${by(PLACES,draft.place).short}落脚。${draft.members.length}位家人，带着${draft.money}两银钱，从自己的日子开始。</p><div class="mini-pairs"><span>首任族长</span><b>${esc(leader?.name||'尚未选择')}</b><span>初始成员</span><b>${draft.members.filter(m=>m.age>=18).length}位成年 · ${draft.members.filter(m=>m.age<18).length}位孩子</b><span>首年银钱预计</span><b class="${(economy?.money||0)>=0?'positive':'negative'}">${economy?signed(economy.money)+' 两':'待完善安排'}</b><span>开局信物</span><b>${draft.relics.length} 件</b></div></section>`;}
function setupView(){return `${worldHeader('setup')}<div class="v3-setup"><aside class="setup-left"><div class="nav-kicker">创建一个家族</div>${STEP_NAMES.map((s,i)=>`<button class="step-link ${step===i?'active':''}" onclick="goStep(${i})" ${step===i?'aria-current="step"':''}><span>0${i+1}</span><div>${s[0]}<small>${s[1]}</small></div></button>`).join('')}<blockquote>开局不是命定的一生。<br>只是决定，<br>从哪里开始。</blockquote></aside><main class="v3-center" id="setup-content"><div class="eyebrow">凡世王朝 · 开篇 ${String(step+1).padStart(2,'0')} / 05</div>${[setupWorld,setupPeople,setupAssets,setupRelics,setupReview][step]()}</main><aside class="budget-side" id="budget-side">${renderBudget()}</aside></div>${setupFooter()}`;}
function setupFooter(){const total=totalPoints(),over=total>LIMIT,errors=step===4?validateDraft():[];return `<footer class="create-footer" id="create-footer"><div class="points-footer"><strong class="${over?'negative':''}">${over?'+':''}${over?round(total-LIMIT):round(LIMIT-total)}</strong><p>${over?'超出的点数':'剩余点数'}<br>${over?'不会自动改动你的选择':'总分 '+LIMIT+' · 不设分类配额'}</p></div><span class="footer-hint">${step===4?'开局后点数不再限制家族的发展。':'修改只保存在开局草案中。'}</span><div class="row">${step?`<button class="btn" onclick="goStep(${step-1})">上一步</button>`:''}${step<4?`<button class="btn primary" onclick="goStep(${step+1})">${['安排家中这些人','安排安身家底','挑选家传旧物','看看这一家'][step]} →</button>`:`<button id="start-game" class="btn primary" onclick="startGame()" ${errors.length?'disabled':''}>立下家谱，开始 →</button>`}</div></footer>`;}
function optionCards(key,options,cls=''){return `<div class="option-grid ${cls}">${options.map(o=>`<button class="option-card ${draft[key]===o.id?'chosen':''}" onclick="setChoice('${key}','${o.id}')" aria-pressed="${draft[key]===o.id}" data-option="${key}-${o.id}"><div class="between"><strong>${esc(o.name)}</strong><div class="cost-selected"><span class="price">${o.cost} 点</span><span class="select-dot">✓</span></div></div><p>${esc(o.desc)}</p>${o.effect?`<div class="option-effect">${esc(o.effect)}</div>`:''}</button>`).join('')}</div>`;}
function setupWorld(){return `<h1 class="page-title">这一家，从怎样的日子开始？</h1><p class="intro-copy">选一个世道，再选一段来历。它们影响起点，不替你决定后来的路。</p><div class="world-ribbon"><div><strong>凡世王朝 · 大晟</strong><p>普通人的一生，与几代人的家业。无修炼、无超自然延寿。</p></div><button class="text-btn" onclick="showWorld()">了解这个世界 ↗</button></div><div class="field-line"><label class="field">家族姓氏 · 不计分<input id="family-name" maxlength="6" value="${esc(draft.family)}" oninput="setFamilyName(this.value)" placeholder="例如：林、沈、司徒"></label><label class="field">开局时间 · 不计分<input id="calendar-year" type="number" min="1" max="9999" value="${draft.calendar}" onchange="setNumber('calendar',this.value,1,1,9999)"><small>大晟历年份；不会增加本局经营年数。</small></label></div>${sectionTitle('生在怎样的时世','每项独立计分；时代以后可能变化')}${optionCards('era',ERA)}${sectionTitle('这个家的来处','只包含写明的效果，不附送人口与家财')}${optionCards('origin',ORIGINS,'origin-grid')}${sectionTitle('在哪一处落脚','选择地区不改变其他配置')}${optionCards('place',PLACES)}<div class="inline-hint">寒门也可以有钱，名门也可以只剩几个人。只要总分不超出，这样的家族同样能开始。</div>`;}
function draftRelation(m){const ps=m.parents.map(id=>draft.members.find(x=>x.id===id)?.name).filter(Boolean);const sp=draft.members.find(x=>x.id===m.spouse);return [ps.length?'父母／养亲：'+ps.join('、'):'本家成员 · 未设上代',sp?'配偶：'+sp.name:''].filter(Boolean).join('　·　');}
function setupPeople(){const adult=draft.members.filter(m=>m.age>=18).length;return `<h1 class="page-title">一个家，由这些人开始。</h1><p class="intro-copy">每个人都能单独设定。人数、资质与已有本领分别计分，只有一个共同预算。</p><div class="family-meta"><div class="mini-stat"><span>入谱人数</span><strong>${draft.members.length}<small style="font:11px var(--sans)"> 人</small></strong></div><div class="mini-stat"><span>成年族人</span><strong>${adult}<small style="font:11px var(--sans)"> 人</small></strong></div><div class="mini-stat"><span>成员总分</span><strong>${pointGroups().filter(g=>['population','talent','experience'].includes(g.id)).reduce((s,g)=>s+g.value,0)}<small style="font:11px var(--sans)"> 点</small></strong></div></div><div class="roster-create">${draft.members.map(m=>{const p=memberPoints(m);return `<article class="draft-person"><div class="name-stamp">${esc(m.name.slice(-1))}</div><div><h3>${esc(m.name)}${draft.leader===m.id?tag('首任族长','red'):''}</h3><div class="byline">${m.age}岁 · ${esc(m.sex)} · ${esc(draftRelation(m))}</div><div class="person-bottom">${TALENTS[m.talent-1].name}资质 · ${FOCUSES[m.focus]} · ${by(EXPERIENCES,m.experience).name}<br>初始安排：${JOBS[m.job]?.name||'尚未选择'}</div></div><div class="person-actions"><span class="price">${p.population+p.talent+p.experience} 点</span><button class="text-btn" onclick="openDraftPerson(${m.id})">编辑这个人 ↗</button>${draft.leader!==m.id&&m.age>=18?`<br><button class="text-btn" onclick="draftLeader(${m.id})">选为族长</button>`:''}</div></article>`}).join('')}</div><div class="add-person"><p class="small-note">没有固定的人数套餐。增加或移除成员，不改动其他人的资质与本领。</p><button class="btn small" onclick="addDraftPerson()">＋ 添一位家人</button></div>${sectionTitle('人数的分数怎么算','仅代表起点条件，不给人物价值分级')}<div class="notice">0—17 岁：每人 4 点。18—54 岁：每人 8 点。55—92 岁：每人 6 点。<br>资质与本领另行加总；名字、性别、亲属关系、首任族长不额外收费。</div><div class="inline-hint">至少留一位成年成员主持开局。父母或养亲与孩子的年龄需要相差至少 18 岁；这些是关系校验，不是配点配额。</div>`;}
function resourceStepper(key,title,unit,increment,unitCost,desc){return `<div class="resource-row"><div><h3>${title}</h3><p>${desc}</p></div><div class="stepper"><button aria-label="减少${title}" onclick="changeResource('${key}',-${increment})">−</button><input aria-label="${title}数量" type="number" min="0" step="${increment}" value="${draft[key]}" onchange="setNumber('${key}',this.value,${increment},0,100000)"><button aria-label="增加${title}" onclick="changeResource('${key}',${increment})">＋</button></div><span class="price">${round(draft[key]/increment*unitCost)} 点</span></div>`;}
function setupAssets(){return `<h1 class="page-title">给日子，留一点本钱。</h1><p class="intro-copy">来历与家底分别选择。可以富而人少，也可以人多而清贫，没有“必须平衡”的规则。</p><section class="panel" style="padding:21px">${resourceStepper('money','手中现银','两',10,1,'每 10 两 1 点；求学、治病和日常开支都从这里来。')}${resourceStepper('grain','储备粮食','石',4,1,'每 4 石 1 点；成年人每年吃用 2 石，孩子 1 石。')}${resourceStepper('land','自家田地','亩',1,4,'每亩 4 点；每年额外收粮 4 石，属于共同家业。')}</section>${sectionTitle('住在哪里','住宅是独立项目，不随出身自动赠送')}${optionCards('home',HOMES)}${sectionTitle('是否已有产业','没有也能靠个人主业谋生，以后可以置办')}<div class="option-grid">${[['workshop','一间木工作坊',14,'有族人从事手艺谋生时，每年额外收入 8 两。'],['shop','一间小商铺',20,'有族人外出经商时，每年额外收入 10 两。']].map(x=>`<button class="option-card ${draft[x[0]]?'chosen':''}" onclick="setToggle('${x[0]}')" aria-pressed="${draft[x[0]]}"><div class="between"><strong>${x[1]}</strong><span class="price">${x[2]} 点 ${draft[x[0]]?'✓':''}</span></div><p>${x[3]}</p></button>`).join('')}</div>${sectionTitle('家中相处的习惯','共同生活的偏向，不改写每个人的性格')}${optionCards('habit',HABITS)}${sectionTitle('可往来的人','所有具体效果都写在选项里')}${optionCards('tie',TIES)}`;}
function relicCard(r,context='setup'){const unlocked=store.profile.unlocked.includes(r.id),chosen=draft.relics.includes(r.id);return `<article class="panel relic-choice ${!unlocked?'locked':''} ${context==='setup'&&chosen?'option-card chosen':''}"><div class="between"><div class="mark">${esc(r.mark)}</div><span class="price">${unlocked?(r.cost+' 点'):'尚未解锁'}</span></div><h3>${esc(r.name)}</h3><div class="relic-type">${esc(r.type)}${r.base?' · 初始可选':''}</div><p>${esc(r.desc)}</p><div class="relic-condition">${unlocked?esc(r.effect):'解锁线索：'+esc(r.clue)}</div><div class="relic-options"><button class="text-btn" onclick="openCollectionRelic('${r.id}')">${unlocked?'查看故事入口':'看看解锁线索'} ↗</button>${context==='setup'?`<button class="btn small ${chosen?'soft':''}" onclick="toggleRelic('${r.id}')" ${!unlocked?'disabled':''}>${chosen?'✓ 已带入，可移除':'选择带入'}</button>`:tag(unlocked?'已解锁':'待发现',unlocked?'green':'outline')}</div></article>`;}
function setupRelics(){return `<h1 class="page-title">带上哪一段旧故事？</h1><p class="intro-copy">现在有 ${store.profile.unlocked.length} 件信物可选。解锁的是开局资格；本局带入哪些，仍由你分配点数。</p><div class="notice" style="margin-bottom:20px">可以不带，也可以带多件；不另设信物名额。每件信物的点数，与来历、人数、家底共用这 ${LIMIT} 点。</div>${sectionTitle('已经可以带入','不同物件，带来不同的事件') }<div class="option-grid relic-grid">${RELICS.filter(r=>store.profile.unlocked.includes(r.id)).map(r=>relicCard(r)).join('')}</div>${sectionTitle('以后，家里还会留下什么','完成相关经历，才能解锁为新的开局选择')}<div class="option-grid relic-grid">${RELICS.filter(r=>!store.profile.unlocked.includes(r.id)).map(r=>relicCard(r)).join('')||'<p class="small-note">这个原型中的信物已全部解锁。旧物仍有各自适合的开局。</p>'}</div><div class="inline-hint">重新开局不会清空解锁记录，也不会提高总分上限。新的物件提供不同的故事，不把所有效果叠加给下一家。</div>`;}
function setupReview(){const errors=validateDraft(),b=draftEstimate(),l=draft.members.find(m=>m.id===draft.leader);return `<h1 class="page-title">家谱的第一页，由你落笔。</h1><p class="intro-copy">设定不会预先保证成功。家族接下来成为什么，取决于每个人如何生活。</p><div class="first-page"><div class="eyebrow">大晟历 ${draft.calendar} 年 · ${by(ERA,draft.era).name}</div><h2>${esc(draft.family||'未名')}氏 · 初记</h2><p>${by(ORIGINS,draft.origin).name}出身，${draft.members.length}位家人在${by(PLACES,draft.place).short}安了家。手中有${draft.money}两银钱，仓里有${draft.grain}石粮。</p><p>${esc(l?.name||'尚待选定的人')}将主持家中的共同事务。其他家人各有安排，也各有自己的前途。</p><p>${draft.relics.length?'带来的旧物有'+draft.relics.map(id=>relicDef(id).name).join('、')+'。它们的来处，也许会在后来慢慢清楚。':'这一回没有带着特别的旧物。从今天起发生的事情，也值得后来的人记住。'}</p><p>从这一年起，开始写下这个家的日子。</p></div><div class="review-lines"><div><span>成员安排</span><b>${draft.members.map(m=>esc(m.name)+' · '+JOBS[m.job].name).join('<br>')}</b></div><div><span>家风与人情</span><b>${by(HABITS,draft.habit).name}／${by(TIES,draft.tie).name}</b></div><div><span>首年家计</span><b>生产 ${b.income} 两 − 培养 ${b.training} 两 − 日常 ${b.upkeep} 两${b.foodCost?' − 购粮 '+b.foodCost+' 两':''}<br><span class="${b.money>=0?'positive':'negative'}">预计结余 ${signed(b.money)} 两</span>。不含你之后处理的事件。</b></div></div><div class="review-total"><span>全部开局项目合计</span><strong class="${totalPoints()>LIMIT?'negative':''}">${totalPoints()} / ${LIMIT} 点</strong></div>${errors.length?`<div class="error-box"><strong>还有几处需要你调整</strong><br>${errors.map(esc).join('<br>')}</div>`:`<div class="followup">开局检查通过。每一项都已计分，人物关系可以成立。没有对任何类别设置额外配额。</div>`}<p class="small-note" style="margin-top:18px">本版为规则与交互原型。年度、物价、寿命与出生使用简化模型；完整官场、战争、个人财产和世界迁移尚未实现。数值用于体验，不是最终平衡。</p>`;}
function refreshSetupBits(){const e=$('#budget-side');if(e)e.innerHTML=renderBudget();const f=$('#create-footer');if(f)f.outerHTML=setupFooter();save();}
function goStep(n){step=clamp(n,0,4);screen='setup';render();window.scrollTo(0,0);}
function showSetup(){closeModal();screen='setup';render();window.scrollTo(0,0);}
function returnGame(){if(!state)return;closeModal();screen='game';render();window.scrollTo(0,0);}
function showCollection(){closeModal();screen='collection';render();window.scrollTo(0,0);}
function showWorld(){closeModal();screen='world';render();window.scrollTo(0,0);}
function setChoice(k,id){draft[k]=id;save();render();}
function setToggle(k){draft[k]=!draft[k];save();render();}
function setFamilyName(value){draft.family=value.slice(0,6);refreshSetupBits();}
function setNumber(k,v,inc,min,max){const n=Number(v);if(!Number.isFinite(n))return;draft[k]=clamp(Math.round(n/inc)*inc,min,max);save();render();}
function changeResource(k,delta){draft[k]=Math.max(0,draft[k]+delta);save();render();}
function draftLeader(id){const m=draft.members.find(m=>m.id===id);if(m&&m.age>=18){draft.leader=id;save();render();toast(m.name+'将成为首任族长，其他安排保留。');}}
function toggleRelic(id){if(!store.profile.unlocked.includes(id))return;draft.relics=draft.relics.includes(id)?draft.relics.filter(x=>x!==id):[...draft.relics,id];save();render();}
function openPriceDetail(){showDialog('每一项，怎样计分',`<div class="help">没有分类额度，也不会自动帮你均衡。</div>${pointGroups().map(g=>`<div class="form-group"><div class="between"><h3>${g.name}</h3><span class="price">共 ${g.value} 点</span></div>${g.entries.length?g.entries.map(e=>`<div class="between small-note" style="padding:6px 0"><span>${esc(e[0])}</span><span>${e[1]} 点</span></div>`).join(''):'<p class="small-note">未选择，不计分。</p>'}</div>`).join('')}<div class="review-total"><span>总分</span><strong>${totalPoints()} / ${LIMIT}</strong></div>`,`<button class="btn primary" onclick="closeModal()">明白了</button>`);}
function collectionView(){const rs=RELICS.filter(r=>collectionFilter==='all'||(collectionFilter==='open'?store.profile.unlocked.includes(r.id):!store.profile.unlocked.includes(r.id)));return `${worldHeader('collection')}<main class="center-library"><div class="library-lead"><div><div class="eyebrow">凡世王朝 · 你的历次发现</div><h1 class="page-title">一个家结束，故事的入口留下。</h1><p class="intro-copy">这里收藏的是未来开局可以选择的信物，不是当前家族的仓库。</p></div><div class="library-count">${store.profile.unlocked.length}<small> / ${RELICS.length} 件已解锁</small></div></div><div class="notice">初始开放三件。完成信物故事或真实的个人经历，才会得到新的开局资格。总分始终是 ${LIMIT}，解锁不增加预算。</div><div class="tabs" style="margin-bottom:20px">${[['all','全部旧物'],['open','已经解锁'],['locked','仍待发现']].map(x=>`<button class="tab ${collectionFilter===x[0]?'active':''}" onclick="collectionFilter='${x[0]}';render()">${x[1]}</button>`).join('')}</div><div class="catalog-grid">${rs.map(r=>relicCard(r,'collection')).join('')||'<p class="empty">这里已经没有待解锁的信物。</p>'}</div>${sectionTitle('这些旧物，从哪里来','不是刷局次数，而是家族真的经历过')}${store.profile.records.length?store.profile.records.slice().reverse().map(r=>`<article class="collection-record"><strong>${esc(relicDef(r.id).name)}</strong><br>${esc(r.family)}家 · 本局第 ${r.year+1} 年 · ${esc(r.reason)}</article>`).join(''):'<p class="small-note">还没有新的解锁记录。带着老木尺开始，完成它的寻访，就能发现第一件新信物。</p>'}${sectionTitle('已经写下的家族终章')}${store.profile.endings.length?store.profile.endings.slice().reverse().map(e=>`<div class="collection-record">${esc(e.family)}氏 · ${esc(e.title)}<br>经营 ${e.year} 年后落笔。只记本轮确认的主终章。</div>`).join(''):'<p class="small-note">家谱还在等着第一段完整的人生。</p>'}<div class="row button-row-wrap" style="margin-top:28px"><button class="btn" onclick="showSetup()">回到开局配点</button>${state?'<button class="btn primary" onclick="returnGame();navigate(\'relics\')">查看本局持有物</button>':''}<button class="text-btn" onclick="exportSave()">导出本地存档 ↗</button></div></main>`;}
function worldView(){return `${worldHeader('world')}<main class="center-library"><div class="eyebrow">第一个世界 · 先把这几代人过明白</div><h1 class="page-title">凡世王朝</h1><p class="intro-copy">大晟，是这个虚构世界的起点。人有寿数，家可以比一任族长活得更久。</p><div class="option-grid"><article class="panel world-card"><h2>每个人，都能安排。</h2><p>读书、谋生、学艺、学医、习武、料理家事与休养。主业持续执行，出师之后也由你决定去向。婚事、照护与家业不会因换任消失。</p></article><article class="panel world-card"><h2>时世会变，家史继续。</h2><p>世界历与本局年数分开。原型已接入时代收支变化、地区差异和全家迁居。没有修炼或超自然延寿，不会因为改了年号就获得几十年经营记录。</p></article><article class="panel world-card"><h2>有取舍，没有配额。</h2><p>总分 ${LIMIT}。来历、人口、资质、经验、家底、人情与信物独立计价。不强求全选，也不强制均衡；允许超分编辑，但超分不能开局。</p></article><article class="panel world-card"><h2>旧物有后文。</h2><p>初始三件信物，原型共七件可收集。解锁只提供新的开局选项，不提高分数。信物可能在本局事件中获得，不需要先解锁才可遇见。</p></article></div>${sectionTitle('此版已经可以体验')}<div class="notice">自由配点与亲属校验；全员安排、出师选择、婚配、生育意愿、收养与族长更替；年度收支、基础家业、迁居与时代变化；信物调查、托付、出售与跨局解锁；13 条可实际判定的凡世终章。</div>${sectionTitle('后续篇目，不冒充已完成')}<p class="help">完整官场与战争、个人独立财产、异地支系经营和更复杂的家族关系尚未接入。其他世界以后逐个讨论。上一版 144 条结局草案保留在「凡世终章」的设定目录中，当前只呈现与凡世有关的条目；设计条目不参与结算。</p><div class="row button-row-wrap" style="margin-top:25px"><button class="btn primary" onclick="showSetup()">创建这一家 →</button><button class="btn" onclick="openHelp()">原型玩法与存档</button></div></main>`;}
function navigate(p){page=p;screen='game';render();window.scrollTo(0,0);}
function gameView(){if(!state){screen='setup';return setupView();}const navs=[['overview','家族近况'],['members','全体族人'],['estate','家业账本'],['relics','传家旧物'],['leaders','历任族长'],['history','家族年鉴'],['endings','凡世终章']];return `<div class="game-shell"><aside class="sidebar"><div class="brand"><div class="seal">${esc(state.family.slice(0,1))}</div><div><div class="brand-name">家业</div><div class="brand-sub">纯文字 · 家族人生</div></div></div><div class="nav-kicker">这一家人的故事</div><nav class="nav" aria-label="家族导航">${navs.map((x,i)=>`<button class="${page===x[0]?'active':''}" onclick="navigate('${x[0]}')" ${page===x[0]?'aria-current="page"':''}><span class="n">0${i+1}</span>${x[1]}${x[0]==='members'?`<span class="count">${living().length}</span>`:x[0]==='relics'?`<span class="count">${state.relics.filter(r=>r.status!=='sold').length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-note"><div class="line"></div><div class="sidebar-quote">人来人往，<br>家谱还在往下写。</div><div class="save-note"><span data-save></span><br>凡世原型 V4 · 无需联网<br><button class="text-btn" onclick="exportSave()" style="font-size:10px">导出一份存档 ↗</button></div></div></aside><main class="main"><header class="topbar"><div class="crumb"><b class="mobile-brand">家业</b>${esc(state.family)}氏家族<span>/</span>${by(PLACES,state.place).short}</div><div class="top-actions"><span class="version">凡世王朝 · V4</span><button class="text-btn" onclick="showCollection()">信物藏阁 ${store.profile.unlocked.length}/7</button><button class="text-btn" onclick="openHelp()">玩法</button><button class="text-btn" onclick="showSetup()">另起家谱</button></div></header><div class="content">${({overview:overviewView,members:membersView,estate:estateView,relics:relicsView,leaders:leadersView,history:historyView,endings:endingsView}[page]||overviewView)()}</div></main>${gameFooter()}</div>`;}
function gameFooter(){const leader=get(state.leader);let title=state.ended?'这一轮家史，已经落笔。':'第 '+(state.elapsed+1)+' 年 · '+living().length+' 位族人的安排已保留';let sub=state.ended?'人物与家族年鉴仍可翻阅。':state.events.length?state.events.length+' 件家事待决定，处理后再过一年。':'不调整，就按原来的安排继续。';let action=state.ended?'阅读本局终章':(!leader?.alive&&adults().length?'选择新族长':state.events.length?'先处理眼前的家事':'按安排，度过这一年');return `<footer class="yearbar"><div><div class="yearbar-title">${title}</div><div class="yearbar-sub">${sub}</div></div><button class="advance-btn" id="advance-year" onclick="advanceYear()">${action}<span class="arrow">→</span></button></footer>`;}
function worldStrip(){return `<div class="game-world-strip"><div><span class="calendar">大晟历 ${state.calendar+state.elapsed} 年</span>　${tag(by(ERA,state.era).name,'outline')}</div><div class="quick-facts">${tag(by(ORIGINS,state.config.origin).name)}${tag('已经营 '+state.elapsed+' 年')}${tag('开局 '+totalPoints(state.config)+' 点')}</div></div>`;}
function overviewView(){const b=estimate(state),l=get(state.leader),headline=state.ended?'这一家人的日子，留在了家谱里。':state.elapsed===0?'从这一年，慢慢过成一个家。':state.lastSummary?.deaths?'有人离开，也有人接过担子。':state.metrics.stable===0?'日子紧一些，还可以重新安排。':'又过了一年，家里有了些变化。';const ready=state.ended?[]:readyEndings();return `${worldStrip()}<section class="intro"><div class="eyebrow">${state.ended?'本局终章':'家族第 '+(state.elapsed+1)+' 年 · 秋'}</div><h1>${headline}</h1><p>${state.elapsed===0?'看看每个人正在做什么，再处理眼前的家事。开局只是起点。':'看一看这一年的后文，再安排下一年的日子。'}</p></section>${state.ended?`<div class="end-banner"><div class="between"><h2>${esc(state.ended.title)}</h2><button class="btn" onclick="showConclusion()">阅读结局</button></div><p>本轮已结束；不会再推进或改动人物。</p></div>`:ready.length?`<div class="followup" style="margin-bottom:22px">已经具备 ${ready.length} 条终章的落笔资格。你可以继续经营，也可以选择一个家族结局。<button class="text-btn" onclick="navigate('endings')" style="margin-left:10px">看看走到了哪里 →</button></div>`:''}<section class="stats"><div class="stat"><div class="stat-label">在世族人</div><div class="stat-value">${living().length}<small>人</small></div><div class="stat-note">家谱已至第 ${Math.max(...state.members.map(m=>m.gen))} 代</div></div><div class="stat"><div class="stat-label">家中积蓄</div><div class="stat-value">${fmt(state.money)}<small>两</small></div><div class="stat-note">预计 <span class="${b.money>=0?'positive':'negative'}">${signed(b.money)} 两／年</span></div></div><div class="stat"><div class="stat-label">存粮</div><div class="stat-value">${fmt(state.grain)}<small>石</small></div><div class="stat-note">全家每年吃用 ${b.eat} 石</div></div><div class="stat"><div class="stat-label">乡里声望</div><div class="stat-value">${state.reputation}<small>/100</small></div><div class="stat-note">${state.reputation>=70?'乡邻愿意来敲这扇门':'从来往与相处中积累'}</div></div></section><div class="dash"><div class="stack">${state.events.length&&!state.ended?decisionView():settledView()}<section class="panel"><div class="panel-head"><h2>家里近来</h2><button class="text-btn" onclick="navigate('history')">翻阅年鉴 ↗</button></div><div class="timeline">${state.logs.slice(-3).reverse().map(timelineItem).join('')}</div></section><div class="family-route"><div class="between"><span class="small">这一回，留下了什么？</span><button class="text-btn" onclick="navigate('relics')">看看传家旧物 →</button></div><p>${state.relics.some(r=>r.phase===1&&r.status!=='sold')?'有人正在查访旧物的来处。新的消息，会在时间推进后送到。':'一些东西在家里传过几双手，慢慢就有了自己的故事。'}</p></div></div><div class="stack">${leaderCard(l)}<section class="panel"><div class="panel-head"><h2>每个人的安排</h2><button class="text-btn" onclick="navigate('members')">全部 ${living().length} 人 ↗</button></div><div class="roster">${living().slice(0,5).map(m=>`<button class="roster-person" onclick="openMember(${m.id})"><span class="name-stamp">${esc(m.name.slice(-1))}</span><span class="person-summary"><strong>${esc(m.name)}</strong><small>${m.age}岁</small><p>${JOBS[m.job].name} · ${TALENTS[m.talent-1].name}资质</p></span><span class="chevron">›</span></button>`).join('')}</div><div class="roster-foot">主业持续保留；转行与接任由你决定。</div></section><div class="overview-advice">${state.relics.some(r=>r.phase===1)?'信物调查不会替换人物主业。下一年既结算生活，也继续调查。':'换族长不重置其他人。信物解锁跨局保留，但点数上限不会增长。'}</div></div></div>`;}
function leaderCard(m){const cur=state.leaders.at(-1);return `<section class="panel leader"><div class="between"><div class="leader-label">现任族长</div>${tag('第 '+state.leaders.length+' 任','outline')}</div><div class="leader-name">${m?.alive?esc(m.name):'虚位以待'}${m?.alive?`<small>${m.age}岁</small>`:''}</div><div class="leader-era">${m?.alive?'第 '+(cur.start+1)+' 年接任 · 已主事 '+(state.elapsed-cur.start)+' 年':'换一任族长，家里的日子继续。'}</div><div class="leader-trait">${m?.alive?'主持家中共同事务，也继续自己的'+JOBS[m.job].name+'。':'没有成年族人时，暂由家人共同照料。孩子长大后可以接任。'}<br><strong>不因换任重置关系、安排或信物。</strong></div><div class="leader-btns"><button class="btn" onclick="openLeader()" ${state.ended?'disabled':''}>${m?.alive?'更换族长':'选择族长'}</button>${m?.alive?`<button class="btn" onclick="openMember(${m.id})">查看这个人</button>`:''}</div></section>`;}
function decisionView(){const e=state.events[0],d=eventData(e);if(!d)return settledView();return `<section class="panel decision" id="decision"><div class="panel-head"><h2>${e.type.startsWith('relic')?'一件旧物，有了新的线索':'有件家事，等你决定'}</h2>${tag('待决定 · '+state.events.length,'red')}</div><div class="panel-body"><h3 class="decision-title">${esc(d.title)}</h3><p class="letter">${esc(d.body)}</p><div class="event-source">${esc(d.source)}</div>${d.actorSelectable?`<label class="actor-field">这件事交给谁来办<select id="event-actor" onchange="chooseActor(this.value)">${adults().map(m=>`<option value="${m.id}" ${(e.actor||d.actor||state.leader)===m.id?'selected':''}>${esc(m.name)} · ${JOBS[m.job].name}</option>`).join('')||'<option>目前没有成年族人</option>'}</select></label>`:'<div style="height:16px"></div>'}<div class="choice-list">${d.choices.map((o,i)=>`<button class="choice ${activeEventChoice===i?'selected':''}" onclick="chooseEvent(${i})" aria-pressed="${activeEventChoice===i}" ${!affordable(o)?'disabled':''} data-event-choice="${i}"><span class="choice-mark"></span><span><span class="choice-title">${esc(o.label)}</span><div class="choice-desc">${esc(o.desc)}${!affordable(o)?'（当前储备不足）':''}</div></span></button>`).join('')}</div><div class="choice-footer"><p>这一次的处理，会留在家族年鉴里。</p><button class="btn primary" id="confirm-event" onclick="resolveEvent('${e.id}')" ${activeEventChoice==null?'disabled':''}>作出决定</button></div></div></section>`;}
function settledView(){return `<section class="settled" id="decision"><div class="result-tick">${state.ended?'这一轮，已落笔':'✓　眼前的家事已处理'}</div><h2>${state.ended?'人来人往，记载还在。':state.lastDecision?'你的决定，已经有了回应。':'每个人都在按安排生活。'}</h2><p>${esc(state.ended?'仍可查看所有人物、旧物和历任族长留下的记录。':state.lastDecision?.body||'可以再看看家里人的近况，也可以让这一年继续。')}</p>${state.lastDecision?.effects.length?`<div class="effects">${state.lastDecision.effects.map(x=>`<span class="effect">${esc(x)}</span>`).join('')}</div>`:''}</section>`;}
function timelineItem(l){return `<article class="timeline-item"><div class="timeline-meta">第 ${l.year+1} 年 · ${esc(l.type)}</div><h3>${esc(l.title)}</h3><p>${esc(l.body)}</p>${l.effects?.length?`<div class="effects">${l.effects.map(x=>`<span class="effect">${esc(x)}</span>`).join('')}</div>`:''}</article>`;}
function personRelation(m){const parents=m.parents.map(id=>get(id)?.name).filter(Boolean),sp=get(m.spouse);return [m.role||'',parents.length?'父母／养亲：'+parents.join('、'):'',sp?'配偶：'+sp.name+(sp.alive?'':'（已故）'):''].filter(Boolean).join(' · ')||'本家成员';}
function membersView(){return `${pageHead('不是人口单位，是每一段人生','全体族人','学习、谋生、照料家人；每个人都能单独安排。',tag(living().length+'人在世 · '+state.members.length+'人入谱','outline'))}<div class="tools"><div class="tabs">${[['alive','全体在世'],['adults','成年族人'],['children','孩子们'],['dead','已故族人']].map(x=>`<button class="tab ${memberFilter===x[0]?'active':''}" onclick="memberFilter='${x[0]}';render()">${x[1]}</button>`).join('')}</div><input class="search" aria-label="查找族人" placeholder="按姓名查找…" value="${esc(memberQuery)}" oninput="searchPeople(this.value)"></div><section class="panel table-wrap" id="people-table">${membersTable()}</section><div class="between" style="margin-top:20px"><p class="small-note">已故者的人生不会从家谱中消失。族长也有自己的主业。</p><button class="btn small" onclick="openAdoption()" ${state.ended?'disabled':''}>照料一位新家人</button></div>`;}
function membersTable(){const ms=state.members.filter(m=>(memberFilter==='dead'?!m.alive:m.alive)&&(memberFilter==='adults'?m.age>=18:memberFilter==='children'?m.age<18:true)&&m.name.includes(memberQuery));return ms.length?`<table class="member-table"><thead><tr><th>族人</th><th>年龄／辈分</th><th>长期安排</th><th>资质与倾向</th><th></th></tr></thead><tbody>${ms.map(m=>`<tr class="${m.alive?'':'dead'}"><td><div class="row"><span class="name-stamp">${esc(m.name.slice(-1))}</span><div><span class="person-name">${esc(m.name)}</span> ${m.id===state.leader?tag('族长','red'):''}<div class="relation">${esc(personRelation(m))}</div></div></div></td><td>${m.age} 岁<div class="job-sub">第 ${m.gen} 代</div></td><td>${m.alive?JOBS[m.job].name:'人生已落笔'}<div class="job-sub">${m.alive?'已累计 '+(m.jobYears[m.job]||0)+' 年':'第 '+(m.deathYear+1)+' 年离世'}</div></td><td>${tag(TALENTS[m.talent-1].name)}<div class="job-sub">${FOCUSES[m.focus]}</div></td><td><button class="btn small" onclick="openMember(${m.id})">${m.alive&&!state.ended?'查看与安排':'翻阅人生'} →</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">这里暂时没有符合条件的族人。</div>';}
function searchPeople(value){memberQuery=value;$('#people-table').innerHTML=membersTable();}
function leadersView(){return `${pageHead('这个家，不止一任人来撑','历任族长','可以主动交接，也可以在离世之后选任。每一任都在同一局家族人生里。',`<button class="btn primary" onclick="openLeader()" ${state.ended?'disabled':''}>选择新族长</button>`)}<div class="notice">任意在世、年满 18 岁的家族成员都可以接任，不限性别与支系。前任至少实际主持一年，才计入终章所需的真实交接；同年轮流任命不会刷出传承。</div><div class="successions">${state.leaders.map((h,i)=>{const m=get(h.id);return `<article class="panel success-card"><div class="ordinal">${String(i+1).padStart(2,'0')}<small>第 ${i+1} 任</small></div><div><h2>${esc(m.name)} ${h.end==null?tag('现任','green'):''}</h2><p>${esc(h.reason)}</p><div class="tenure">第 ${h.start+1} 年 — ${h.end==null?'至今':'第 '+(h.end+1)+' 年'} · ${m.alive?'在世，'+m.age+' 岁':'享年 '+m.age+' 岁'}</div></div><button class="btn small" onclick="openMember(${m.id})">查看人生 →</button></article>`}).join('')}</div>`;}
function historyView(){const years=[...new Set(state.logs.map(l=>l.year))].sort((a,b)=>b-a);return `${pageHead('人来人往，总有记载','家族年鉴','安排、选择、解锁与后来发生的事，都在这里。',tag(state.logs.length+' 则记事','outline'))}${years.map(y=>`<section class="history-group"><div class="history-year">第 ${y+1} 年<small>大晟历 ${state.calendar+y} 年</small></div><div class="panel"><div class="timeline" style="padding-top:20px">${state.logs.filter(l=>l.year===y).reverse().map(timelineItem).join('')}</div></div></section>`).join('')}`;}
function estateView(){const b=estimate(state);return `${pageHead('收入有来处，支出也有去处','家业账本','这里先管理全家的共同资产。个人独立财产与异地支系账目留待后续实现。')}${worldStrip()}<div class="dash"><div class="stack"><section class="panel"><div class="panel-head"><h2>照当前安排，过这一年</h2>${tag('预计收支','outline')}</div><div class="mini-ledger"><div class="between"><span>生产与谋生所得</span><span class="positive">+${b.income} 两</span></div><div class="between"><span>读书、学艺等培养</span><span>−${b.training} 两</span></div><div class="between"><span>生活、住宅与租金</span><span>−${b.upkeep} 两</span></div><div class="between"><span>预计补买口粮</span><span>−${b.foodCost} 两</span></div><div class="between"><span>预计年度净结余</span><span class="${b.money>=0?'positive':'negative'}">${signed(b.money)} 两</span></div></div></section><div class="ledger-assets"><article class="panel"><h3>${state.land} 亩田地</h3><p>每年额外收粮 ${state.land*4} 石。田产之外，务农族人仍有各自的收成。</p><button class="btn small" onclick="confirmPurchase('land')" ${state.ended?'disabled':''}>置一亩田 · 60 两</button></article><article class="panel"><h3>${by(HOMES,state.home).name}</h3><p>${by(HOMES,state.home).desc}</p><button class="btn small" onclick="confirmPurchase('home')" ${state.ended||state.home==='courtyard'||state.home==='estate'?'disabled':''}>安置小院 · 100 两</button></article><article class="panel"><h3>木工作坊 ${state.workshop?'· 已有':''}</h3><p>有人从事手艺谋生时，每年额外收入 8 两。无人经营时不产生额外收入。</p><button class="btn small" onclick="confirmPurchase('workshop')" ${state.ended||state.workshop?'disabled':''}>${state.workshop?'本家已置办':'置办作坊 · 140 两'}</button></article><article class="panel"><h3>小商铺 ${state.shop?'· 已有':''}</h3><p>有人经商时，每年额外收入 10 两。不改变这个人的长期安排。</p><button class="btn small" onclick="confirmPurchase('shop')" ${state.ended||state.shop?'disabled':''}>${state.shop?'本家已置办':'置办商铺 · 200 两'}</button></article></div></div><div class="stack"><section class="panel" style="padding:22px"><h2 style="font:21px var(--serif)">家里的储备</h2><div class="mini-pairs"><span>积蓄</span><b>${fmt(state.money)} 两</b><span>存粮</span><b>${fmt(state.grain)} 石</b><span>当前粮价</span><b>${b.foodPrice} 两／石</b><span>年产／年用</span><b>${b.grainEarn}／${b.eat} 石</b></div><div class="row" style="margin-top:20px"><button class="btn small" onclick="buyGrain()" ${state.ended?'disabled':''}>买 10 石粮</button><button class="btn small" onclick="sellGrain()" ${state.ended?'disabled':''}>卖 10 石粮</button></div></section><section class="panel" style="padding:22px"><h2 style="font:21px var(--serif)">在别处重新安家</h2><p class="small-note" style="margin:15px 0">全家一起迁居，保留每个人的主业、亲属关系与信物。搬家费 30 两；本版用一处共同家宅模拟。</p><button class="btn wide" onclick="openMove()" ${state.ended?'disabled':''}>选择迁居地点</button></section><div class="overview-advice">粮食不足时，年度结算会尽量用现银购买；仍有缺口时才影响体魄。缺钱或缺粮不会直接判为家族结束。</div></div></div>`;}
function relicState(r){return r.status==='sold'?'已出售':r.phase===2?'故事已留在家谱':r.phase===1?'查访中 · 第 '+(r.due+1)+' 年有后续':r.deferred?'暂时收好':'还有一段来处待寻';}
function relicsView(){return `${pageHead('当前这个家，实际保有的物件','传家旧物','物件属于家族，保管人可以更换。离世与退位不会把它从家中抹去。',`<button class="btn" onclick="showCollection()">信物藏阁 ${store.profile.unlocked.length}/7 ↗</button>`)}<div class="notice">这里是本局物件；藏阁是跨局解锁。解锁一件新信物，并不会凭空把它加进这一家的行李。</div><div class="catalog-grid">${state.relics.map(r=>{const d=relicDef(r.id),m=get(r.custodian);return `<article class="panel relic-choice ${r.status==='sold'?'locked':''}"><div class="between"><span class="mark">${d.mark}</span>${tag(r.status==='sold'?'已离开家中':r.phase===1?'查访中':'本局持有',r.phase===1?'green':'outline')}</div><h3>${d.name}</h3><div class="relic-type">保管人：${r.status==='sold'?'—':m?.alive?esc(m.name):'收在家中，尚待托付'}</div><p>${d.desc}</p><div class="relic-condition">${r.status==='sold'?'保有效果已停止。已发生的托付与故事仍在家谱里。':d.effect}<br><span class="muted">${relicState(r)}</span></div><div class="relic-options"><button class="text-btn" onclick="openOwnedRelic('${r.id}')">查看物件与往事 ↗</button>${r.phase===0&&r.status!=='sold'&&!state.ended?`<button class="btn small" onclick="investigateRelic('${r.id}')">继续线索</button>`:''}</div></article>`}).join('')||'<div class="empty">开局没有携带特别的旧物。<br>之后的行医等经历，也可能让家里获得新的物件。</div>'}</div>`;}
let endingSearch='';
function endingsView(){return `${pageHead('凡世王朝 · 这个家最终会留下什么','家族终章','满足条件，获得落笔资格。确认一个主终章，才结束这轮游戏。',tag('本世界 · 独立判定','outline'))}${state.ended?`<div class="end-banner"><div class="between"><h2>本局：${esc(state.ended.title)}</h2><button class="btn" onclick="showConclusion()">重读终章</button></div></div>`:''}<div class="notice">本版有 13 条实际接入的演示终章。原有上百条跨世界草案没有删掉：在「后续篇目」中，仅展示与凡世有关的设定；它们尚不参与结算。</div><div class="tools"><div class="tabs"><button class="tab ${endFilter==='live'?'active':''}" onclick="endFilter='live';render()">可实际达成 · 13</button><button class="tab ${endFilter==='ready'?'active':''}" onclick="endFilter='ready';render()">已有落笔资格 · ${readyEndings().length}</button><button class="tab ${endFilter==='design'?'active':''}" onclick="endFilter='design';render()">后续篇目 · 设定</button></div><input class="search" aria-label="查找终章" placeholder="查找名字或方向…" value="${esc(endingSearch)}" oninput="endingSearch=this.value;document.getElementById('ending-results').innerHTML=endingResults()"></div><div id="ending-results">${endingResults()}</div>`;}
function endingResults(){if(endFilter==='design'){const used=new Set(ENDINGS.map(e=>e.title));const list=ORIGINAL_CATALOG.filter(e=>(e.worlds.includes('all')||e.worlds.includes('mortal'))&&!used.has(e.title)&&[e.title,e.category,...e.conditions].join(' ').includes(endingSearch));return `<p class="small-note" style="margin-bottom:17px">${list.length} 条凡世相关草案。条件仍需结合本世界规则重审，不代表这些系统已经制作完成。</p><div class="catalog-grid">${list.map(e=>`<article class="panel catalogue-card"><div class="between"><span class="ending-code">${e.id} · ${e.category}</span>${tag('设定','outline')}</div><h2>${esc(e.title)}</h2><div class="catalogue-conditions">${e.conditions.map(esc).join('；')}。</div><button class="text-btn" onclick="openDesignEnding('${e.id}')">查看终章样稿 ↗</button></article>`).join('')}</div>`;}
 const list=(endFilter==='ready'?readyEndings():ENDINGS).filter(e=>(e.title+e.category+e.desc).includes(endingSearch));return `<div class="ending-grid">${list.map(e=>{const c=e.criteria(),ready=c.every(x=>x[1]>=x[2])&&!e.auto;return `<article class="panel ending-card ${ready?'ending-ready':''}"><div class="between"><span class="ending-num" style="margin:0">${e.category}</span>${tag(e.auto?'不可逆终章':ready?'可以落笔':'继续书写',ready?'green':'outline')}</div><h2 style="margin-top:18px">${e.title}</h2><p class="ending-desc">${e.desc}</p><div class="criteria">${c.map(x=>`<div class="criterion ${x[1]>=x[2]?'done':''}"><div class="criterion-label"><span>${x[1]>=x[2]?'✓ ':''}${esc(x[0])}</span><span style="white-space:nowrap">${Math.min(x[1],x[2])}/${x[2]} ${x[3]}</span></div><div class="progress-track"><div class="progress-fill" style="width:${clamp(x[1]/x[2]*100,0,100)}%"></div></div></div>`).join('')}</div><div class="ending-foot between"><span>${e.auto?'不是族长无后，而是全体族人均已离世。':ready?'可以现在结束，也可以继续经营。':'只统计本局真实经历，不靠开局参数抵扣。'}</span>${ready&&!state.ended?`<button class="btn small" onclick="confirmEnding('${e.id}')">写下终章</button>`:''}</div></article>`}).join('')||'<div class="empty">还没有对应的终章。先把一家人的日子接着过下去。</div>'}</div>`;}


let draftEdit=null,chosenLeader=null,selectedJob=null,selectedBirthPlan=true,pendingImport=null;
function showDialog(title,body,footer='',drawer=false){modalReturn=document.activeElement;$('#modal-root').innerHTML=`<div class="overlay ${drawer?'drawer-wrap':''}" onclick="if(event.target===this)closeModal()"><section class="dialog ${drawer?'drawer drawer-wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="dialog-head"><h2 id="modal-title">${esc(title)}</h2><button class="close" aria-label="关闭窗口" onclick="closeModal()">×</button></div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('#modal-root button:not([disabled])')?.focus(),10);}
function closeModal(){const old=modalReturn;$('#modal-root').innerHTML='';document.body.style.overflow='';if(old?.isConnected)old.focus();}
document.addEventListener('keydown',e=>{const dialog=$('#modal-root [role=dialog]');if(!dialog)return;if(e.key==='Escape'){e.preventDefault();closeModal();return;}if(e.key==='Tab'){const all=[...dialog.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href],[tabindex="0"]')].filter(el=>el.offsetParent!==null);const first=all[0],last=all.at(-1);if(!first)return;if(e.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){e.preventDefault();first.focus();}}});
function openDraftPerson(id){draftEdit=clone(draft.members.find(m=>m.id===id));if(draftEdit)draftPersonDialog(false);}
function addDraftPerson(){draftEdit=rawPerson({id:draft.nextId,name:draft.family+'怀宁',age:18,talent:2,job:'farm'});draftPersonDialog(true);}
function draftPersonDialog(isNew){const m=draftEdit;const relatives=draft.members.filter(x=>x.id!==m.id);showDialog(isNew?'添一位家人':'这个人，最初是什么模样',`<div class="small-note">人数、资质、本领分别计分；修改不会自动改变其他家人。</div><div class="form-grid" style="margin-top:20px"><label class="field">姓名 · 不计分<input id="dp-name" maxlength="16" value="${esc(m.name)}"></label><label class="field">性别 · 不计分<select id="dp-sex">${['男','女'].map(s=>`<option ${m.sex===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">年龄<input type="number" min="0" max="92" id="dp-age" value="${m.age}" oninput="draftPersonEstimate()"><small>人数基础分随年龄阶段计价。</small></label><label class="field">性情 · 不计分<select id="dp-trait">${['踏实','细致','仁厚','好奇','开朗','沉静'].map(t=>`<option ${m.trait===t?'selected':''}>${t}</option>`).join('')}</select><small>本版记录与展示，不参与数值加成。</small></label><label class="field">资质等级<select id="dp-talent" onchange="draftPersonEstimate()">${TALENTS.map((t,i)=>`<option value="${i+1}" ${m.talent===i+1?'selected':''}>${t.name} · ${t.cost} 点</option>`).join('')}</select></label><label class="field">擅长方向 · 不额外计分<select id="dp-focus">${Object.entries(FOCUSES).map(([k,v])=>`<option value="${k}" ${m.focus===k?'selected':''}>${v}</option>`).join('')}</select><small>相应学习安排每年额外成长 +2。</small></label><label class="field" style="grid-column:1/-1">已经掌握的本领<select id="dp-experience" onchange="draftPersonEstimate()">${EXPERIENCES.map(x=>`<option value="${x.id}" ${m.experience===x.id?'selected':''}>${x.name} · ${x.cost} 点</option>`).join('')}</select><small id="dp-exp-desc">${by(EXPERIENCES,m.experience).desc}</small></label><label class="field" style="grid-column:1/-1">初始长期安排<select id="dp-job">${Object.entries(JOBS).map(([k,j])=>`<option value="${k}" ${m.job===k?'selected':''}>${j.name}${jobReason(m,k)?'（'+jobReason(m,k)+'）':''}</option>`).join('')}</select><small>选择本领不会替你选职业；需满足年龄与能力条件。</small></label></div><div class="form-group"><h3>与家里人的关系</h3><div class="form-grid"><label class="field">父母或养亲（一）<select id="dp-parent1"><option value="">未登记</option>${relatives.map(x=>`<option value="${x.id}" ${m.parents[0]===x.id?'selected':''}>${esc(x.name)} · ${x.age}岁</option>`).join('')}</select></label><label class="field">父母或养亲（二）<select id="dp-parent2"><option value="">未登记</option>${relatives.map(x=>`<option value="${x.id}" ${m.parents[1]===x.id?'selected':''}>${esc(x.name)} · ${x.age}岁</option>`).join('')}</select></label><label class="field" style="grid-column:1/-1">配偶<select id="dp-spouse"><option value="">未婚／未登记</option>${relatives.filter(x=>x.age>=18&&(!x.spouse||x.spouse===m.id)).map(x=>`<option value="${x.id}" ${m.spouse===x.id?'selected':''}>${esc(x.name)} · ${x.age}岁</option>`).join('')}</select></label></div><div class="form-explain">父母或养亲与孩子至少相差 18 岁；配偶需成年且不能是直系或同祖近亲。若改变已有配偶，会明确解除原来的双向关系。</div></div><div id="dp-errors"></div><div class="review-total" id="dp-total"></div>${!isNew?`<button class="text-btn negative" onclick="removeDraftPerson(${m.id})">从开局中移除这个人</button>`:''}`,`<p id="dp-total-note">只修改这位家人。</p><button class="btn primary" onclick="saveDraftPerson(${isNew?'true':'false'})">保存这个人</button>`,true);draftPersonEstimate();}
function draftPersonValues(){return {...draftEdit,name:$('#dp-name').value.trim().slice(0,16),sex:$('#dp-sex').value,age:Number($('#dp-age').value),trait:$('#dp-trait').value,talent:Number($('#dp-talent').value),focus:$('#dp-focus').value,experience:$('#dp-experience').value,job:$('#dp-job').value,parents:[...new Set([$('#dp-parent1').value,$('#dp-parent2').value].filter(Boolean).map(Number))],spouse:Number($('#dp-spouse').value)||null};}
function draftPersonEstimate(){if(!$('#dp-age'))return;const m=draftPersonValues(),p=memberPoints(m),sum=p.population+p.talent+p.experience;$('#dp-total').innerHTML=`<span>人数 ${p.population} ＋ 资质 ${p.talent} ＋ 本领 ${p.experience}</span><strong>${sum} 点</strong>`;$('#dp-exp-desc').textContent=by(EXPERIENCES,m.experience).desc;$('#dp-job').innerHTML=Object.entries(JOBS).map(([k,j])=>`<option value="${k}" ${m.job===k?'selected':''}>${j.name}${jobReason(m,k)?'（'+jobReason(m,k)+'）':''}</option>`).join('');$('#dp-total-note').textContent='超分也可以先保存草案，开局前再调整。';}
function saveDraftPerson(isNew){const m=draftPersonValues(),d=clone(draft),old=d.members.find(x=>x.id===m.id);if(old?.spouse&&old.spouse!==m.spouse){const ex=d.members.find(x=>x.id===old.spouse);if(ex)ex.spouse=null;}if(m.spouse){const p=d.members.find(x=>x.id===m.spouse);if(p)p.spouse=m.id;}if(isNew)d.members.push(m);else d.members[d.members.findIndex(x=>x.id===m.id)]=m;const errors=validateDraft(d).filter(t=>!t.startsWith('开局用了'));if(errors.length){$('#dp-errors').innerHTML='<div class="error-box">'+errors.map(esc).join('<br>')+'</div>';$('#dp-errors').scrollIntoView({block:'nearest'});return;}if(isNew)d.nextId=Math.max(d.nextId,m.id+1);draft=d;closeModal();save();render();toast(m.name+'的开局条件已保存。其他家人的设置没有改动。');}
function removeDraftPerson(id){if(draft.leader===id)return toast('先选择另一位首任族长，再移除当前这位。');const m=draft.members.find(x=>x.id===id);showDialog('从开局中移除'+m.name+'？',`<p class="help">只移除这位成员，并解除其他人对其的亲属引用。其他家人的年龄、资质、本领与安排保持不变。</p>`,`<button class="btn" onclick="closeModal()">保留</button><button class="btn primary" onclick="commitRemoveDraft(${id})">移除这个人</button>`);}
function commitRemoveDraft(id){draft.members=draft.members.filter(m=>m.id!==id);draft.members.forEach(m=>{m.parents=m.parents.filter(p=>p!==id);if(m.spouse===id)m.spouse=null;});closeModal();save();render();toast('成员已移除，所涉及的关系已经解除。');}
function openMember(id){const m=get(id);if(!m)return;drawerMember=id;selectedJob=m.job;selectedBirthPlan=m.birthPlan;renderMember();}
function renderMember(){const m=get(drawerMember);if(!m)return;const editable=m.alive&&!state.ended;const spouse=get(m.spouse);showDialog('一个人的一生',`<div class="bio-name"><div class="bio-stamp">${esc(m.name.slice(-1))}</div><div><h3>${esc(m.name)} ${m.id===state.leader?tag('现任族长','red'):''}</h3><p>${m.age} 岁 · 第 ${m.gen} 代 · ${m.alive?'在世':'已故'} · ${esc(m.trait)}</p></div></div><p class="bio-quote">${esc(personRelation(m))}</p><div class="bio-relations">${TALENTS[m.talent-1].name}资质 · ${FOCUSES[m.focus]}<br>体魄 ${m.health}/100${m.examPassed?' · 已通过本局应试':''}</div><div class="person-skills">${Object.entries(STAT_NAMES).map(([k,v])=>`<div><span>${v}</span><strong>${m[k]}</strong></div>`).join('')}</div>${editable?`<div class="section-label between"><span>安排接下来的生活</span>${tag('当前：'+JOBS[m.job].name,'outline')}</div><div class="job-grid">${Object.entries(JOBS).map(([k,j])=>`<button class="job-card ${selectedJob===k?'selected':''}" onclick="selectMemberJob('${k}')" aria-pressed="${selectedJob===k}" ${!candidateHasJob(m,k)?'disabled':''} data-job="${k}"><strong>${j.name}</strong><p>${j.desc}${jobReason(m,k)?'<br>尚需：'+jobReason(m,k):''}</p></button>`).join('')}</div><div class="job-info">长期安排自动保留；达到出师条件时会询问是否转行。婚事与信物调查不占用主业。</div><div class="section-label">家庭与个人事务</div>${m.age>=18?`<label class="row small-note" style="align-items:flex-start"><input id="birth-plan" type="checkbox" ${selectedBirthPlan?'checked':''} onchange="selectedBirthPlan=this.checked"><span>愿意迎来孩子<br><span class="muted">双方意愿开放、年龄与生活条件适合时才可能自然生育，不保证立即发生。</span></span></label><div class="row button-row-wrap" style="margin:16px 0">${!spouse?.alive?`<button class="btn small" onclick="openMarriage(${m.id})">了解婚事</button>`:tag('配偶：'+spouse.name)}${m.learn>=55&&!m.examPassed?`<button class="btn small" onclick="openExam(${m.id})">参加应试</button>`:''}</div>`:'<p class="small-note">孩子也能单独安排；还没有开放成年事务。</p>'}`:''}<div class="section-label">与这个家的往事</div><div class="bio-log">${m.bio.slice().reverse().map(b=>`<p><time>第 ${b.year+1} 年</time>${esc(b.text)}</p>`).join('')}</div>`,`<p>${editable?'主业与生育意愿在保存后生效。':'这一生的经历一直保存在家谱中。'}</p><button class="btn ${editable?'primary':''}" onclick="${editable?'saveMemberJob()':'closeModal()'}">${editable?'保存安排':'收起传记'}</button>`,true);}
function selectMemberJob(k){if(!candidateHasJob(get(drawerMember),k))return;selectedJob=k;document.querySelectorAll('[data-job]').forEach(el=>{const chosen=el.dataset.job===k;el.classList.toggle('selected',chosen);el.setAttribute('aria-pressed',String(chosen));});}
function saveMemberJob(){const m=get(drawerMember);if(!m?.alive||state.ended||!candidateHasJob(m,selectedJob))return;const changed=m.job!==selectedJob;if(changed)setMemberJob(m,selectedJob);if(m.birthPlan!==selectedBirthPlan){m.birthPlan=selectedBirthPlan;personRecord(m,selectedBirthPlan?'愿意在条件适合时迎来孩子。':'暂不计划生育，继续眼下的生活。');record('安排',m.name+'调整了家庭计划',selectedBirthPlan?'在条件适合时，可以迎来孩子。':'暂不生育，不影响这个人的其他安排。',[]);}closeModal();save();render();toast(changed?m.name+'将继续新的安排，下一次年度结算生效。':m.name+'的安排已保留。');}
function openLeader(){if(state.ended)return;chosenLeader=null;const candidates=adults().filter(m=>m.id!==state.leader),cur=get(state.leader);showDialog('把这个家，交给谁？',`<div class="notice">${cur?.alive?esc(cur.name)+'退下以后，仍继续自己的生活。':'上一任已经不在，从成年族人中选一位接手。'}<br>选择不受性别、支系限制；全体族人的安排与信物均保留。</div><div class="candidate-list">${candidates.map(m=>`<button class="candidate" data-leader="${m.id}" onclick="pickLeader(${m.id})"><div class="between"><div class="candidate-name">${esc(m.name)}<small>${m.age} 岁 · 第 ${m.gen} 代</small></div><span class="choice-mark"></span></div><p>目前${JOBS[m.job].name}，已累计 ${m.jobYears[m.job]||0} 年。<br>接任后继续该主业，不清空人生经历。</p></button>`).join('')||'<div class="empty">没有其他成年候选。<br>如果家里暂时只有孩子，可以等待他们长大。</div>'}</div>`,`<p>本轮第 ${state.leaders.length+1} 任族长。</p><button class="btn primary" id="confirm-leader" onclick="commitLeader()" disabled>确认交接</button>`);}
function pickLeader(id){chosenLeader=id;document.querySelectorAll('[data-leader]').forEach(el=>el.classList.toggle('selected',Number(el.dataset.leader)===id));$('#confirm-leader').disabled=false;}
function commitLeader(){const m=get(chosenLeader);if(!m?.alive||m.age<18||state.ended||m.id===state.leader)return;const old=get(state.leader),prior=state.leaders.at(-1),valid=state.elapsed-prior.start>=1;if(prior.end==null)prior.end=state.elapsed;state.leader=m.id;state.leaders.push({id:m.id,start:state.elapsed,end:null,reason:'从'+(old?.name||'前人')+'手中接过共同事务，继续以'+JOBS[m.job].name+'谋生活。'});personRecord(m,'被选为第 '+state.leaders.length+' 任族长。');if(old?.alive)personRecord(old,'卸下族长之位，交给'+m.name+'，继续自己的生活。');if(own('newbook')&&valid)state.reputation=clamp(state.reputation+3,0,100);record('交接',m.name+'成为第 '+state.leaders.length+' 任族长',(old?.alive?old.name+'仍然留在家族中生活。':'前人留下的安排也一并保留。')+'其他人的主业、关系与已经发生的往事没有重置。',[valid?'真实交接已记录':'同年换任不计入传承条件']);closeModal();save();render();toast('族长已经交接给'+m.name+'，这一局继续。');}
function openCollectionRelic(id){const d=relicDef(id),unlocked=store.profile.unlocked.includes(id);showDialog(d.name,`<div class="bio-name"><div class="bio-stamp">${d.mark}</div><div><h3>${d.type}</h3><p>${unlocked?'已解锁 · 可用于新开局':'尚未解锁'} · ${d.cost} 点</p></div></div><p class="bio-quote">${d.desc}</p><div class="notice">${d.effect}</div><div class="section-label">怎样得到开局资格</div><p class="help">${d.clue}</p><div class="relic-detail-steps"><div><strong>解锁的是选择资格</strong><p>不会自动带入每一个新家族，也不会提高总分上限。</p></div><div><strong>本局仍需实际获得</strong><p>开局选择，或在后续生活中获得，才是这一家真实拥有的物件。</p></div><div><strong>有不同的处理方式</strong><p>可以追查、托付或暂时保存。卖掉以后保有效果与未完成调查停止，已发生的历史仍保留。</p></div></div>`,`<button class="btn primary" onclick="closeModal()">收起这件旧物</button>`);}
function openOwnedRelic(id){const r=state.relics.find(x=>x.id===id);if(!r)return;const d=relicDef(id);showDialog(d.name,`<div class="bio-name"><div class="bio-stamp">${d.mark}</div><div><h3>${d.type}</h3><p>${relicState(r)}</p></div></div><p class="bio-quote">${d.desc}</p><div class="notice">${r.status==='sold'?'已经离开家中，保有效果与未完成的后续停止。':d.effect}</div>${!state.ended&&r.status!=='sold'?`<label class="field">交给谁保管<select id="relic-custodian"><option value="">暂存在家中</option>${adults().map(m=>`<option value="${m.id}" ${r.custodian===m.id?'selected':''}>${esc(m.name)} · ${m.age}岁</option>`).join('')}</select></label><div class="row" style="margin:15px 0"><button class="btn small" onclick="transferRelic('${id}')">确认托付</button>${r.phase===0?`<button class="btn small" onclick="investigateRelic('${id}')">继续线索</button>`:''}<button class="text-btn negative" onclick="offerRelicSale('${id}')">出售救急</button></div>`:''}<div class="section-label">它留在家里的这些年</div><div class="bio-log">${r.history.slice().reverse().map(h=>`<p><time>第 ${h.year+1} 年</time>${esc(h.text)}</p>`).join('')}</div>`,`<p>物件与当前保管人是两个不同的记录。</p><button class="btn" onclick="closeModal()">收好</button>`,true);}
function transferRelic(id){const r=own(id);if(!r||state.ended)return;const v=Number($('#relic-custodian').value)||null;if(v&&(!get(v)?.alive||get(v).age<18))return;if(r.custodian===v)return toast('保管人没有改变。');r.custodian=v;const text=v?'交给'+get(v).name+'保管。':'暂存在家中，等待以后托付。';r.history.push({year:state.elapsed,text});record('托付',relicDef(id).name+'有了新的去处',text,[]);save();closeModal();render();toast('托付已记入物件与家族的历史。');}
function investigateRelic(id){const r=own(id);if(!r||r.phase!==0||state.ended)return;r.deferred=false;queueRelic(r);closeModal();page='overview';screen='game';activeEventChoice=null;save();render();window.scrollTo(0,0);}
function relicSaleValue(id){return {book:12,ruler:14,letter:6,plan:30,newbook:18,jade:28,notes:24}[id];}
function offerRelicSale(id){if(!own(id)||state.ended)return;const v=relicSaleValue(id);showDialog('把'+relicDef(id).name+'卖掉？',`<p class="help">可以换得 ${v} 两银钱。出售后，该物件的保有效果与未完成的调查都会停止；相关待决定事件会取消。已经解锁的开局资格与既有历史不会丢失。</p>`,`<button class="btn" onclick="closeModal()">还是留着</button><button class="btn primary" onclick="sellRelic('${id}')">确认出售</button>`);}
function sellRelic(id){const r=own(id);if(!r||state.ended)return;r.status='sold';r.due=null;state.events=state.events.filter(e=>e.relic!==id);activeEventChoice=null;state.money+=relicSaleValue(id);r.history.push({year:state.elapsed,text:'为接上眼前的生活，出售换得 '+relicSaleValue(id)+' 两。'});record('取舍','家里卖掉了'+relicDef(id).name,'保有效果和未完成的调查随之停止，已有往事仍留在家谱中。',['银钱 +'+relicSaleValue(id)+' 两']);closeModal();save();render();toast('物件已经离开家中，未完成调查停止。');}
function spouseCandidates(m){const names=m.sex==='男'?['余知春','谢清和']:['余行舟','谢怀川'];return names.map((n,i)=>({name:state.members.some(x=>x.name===n)?n+state.nextId:n,sex:m.sex==='男'?'女':'男',age:Math.max(18,m.age-2+i),experience:i?'craft':'scholar',job:i?'craft':'teach',trait:i?'细致':'温和'}));}
function openMarriage(id){const m=get(id);if(!m?.alive||m.age<18||get(m.spouse)?.alive||state.ended)return;showDialog(m.name+'的婚事',`<div class="notice">以下均为成年、没有亲属关系且彼此有意的候选。成婚花费 24 两，对方加入家族并可单独安排；不自动立即生育。</div>${spouseCandidates(m).map((p,i)=>`<article class="candidate" style="margin-bottom:12px"><div class="between"><span class="candidate-name">${esc(p.name)}<small>${p.age} 岁</small></span><button class="btn small" onclick="marry(${id},${i})" ${state.money<24?'disabled':''}>议定婚事</button></div><p>${by(EXPERIENCES,p.experience).name}，愿意一起经营生活，也希望继续${JOBS[p.job].name}。</p></article>`).join('')}`,`<p>可以先退出，不作安排。</p><button class="btn" onclick="closeModal()">再想想</button>`);}
function marry(id,index){const m=get(id);if(!m?.alive||m.age<18||get(m.spouse)?.alive||state.ended||state.money<24||![0,1].includes(index))return;const p=spouseCandidates(m)[index],n=newGameMember({...p,...by(EXPERIENCES,p.experience).values,gen:m.gen,spouse:m.id,parents:[]});m.spouse=n.id;state.members.push(n);state.money-=24;n.bio=[{year:state.elapsed,text:'与'+m.name+'成婚，加入'+state.family+'家。'}];personRecord(m,'与'+n.name+'成婚，各自的工作继续。');record('婚嫁',m.name+'与'+n.name+'成婚','家里多了一位能独立安排人生的成员。婚事没有清空双方的本领。',['银钱 −24 两','人口 +1']);closeModal();save();render();toast('婚事已记下，新成员可以单独安排。');}
function openAdoption(){if(state.ended)return;const guardians=adults().filter(m=>m.age>=24);showDialog('照料一位新家人',`<p class="help">为一位六岁的孩子提供安身之处。安置花费 20 两；孩子加入家谱，之后按每年 6 两进行启蒙，可由你调整。领养的孩子拥有同样的成长与继任资格。</p>${!guardians.length?'<div class="error-box">需要一位至少 24 岁的成年族人担任养亲。</div>':''}`,`<button class="btn" onclick="closeModal()">暂不安排</button><button class="btn primary" onclick="adopt()" ${!guardians.length||state.money<20?'disabled':''}>接进家里 · 20 两</button>`);}
function adopt(){if(state.ended||state.money<20||!adults().some(m=>m.age>=24))return;state.money-=20;addRelative('adopt');closeModal();save();render();toast('新的家人已入谱，可以从全体族人中查看。');}
function openExam(id){const m=get(id);if(!m?.alive||m.age<18||m.learn<55||m.examPassed||state.ended)return;const chance=Math.round(clamp((m.learn-30)/80,.25,.85)*100);showDialog(m.name+'准备应试',`<p class="help">参加本世界虚构的取士考试，花费 12 两。本次按学识判定，通过机会约 ${chance}%；失败后可以继续读书、教书或转行。通过不会自动改变主业。</p><div class="inline-hint">同一人每年只能应试一次。此处使用简化判定，不是完整科举与官场模拟。</div>`,`<button class="btn" onclick="closeModal()">再准备一年</button><button class="btn primary" onclick="takeExam(${id})" ${state.money<12||m.lastExam===state.elapsed?'disabled':''}>前往应试 · 12 两</button>`);}
function takeExam(id){const m=get(id);if(!m?.alive||m.age<18||m.learn<55||m.examPassed||state.ended||m.lastExam===state.elapsed||state.money<12)return;state.money-=12;m.lastExam=state.elapsed;const pass=rnd()<clamp((m.learn-30)/80,.25,.85);if(pass){m.examPassed=true;state.metrics.exam++;state.reputation=clamp(state.reputation+8,0,100);}const text=pass?'通过了应试。可以继续读书或教书，也可以由你安排地方任职。':'这一次没有通过。学过的本领都还在，下一年仍可以再试。';personRecord(m,text);record('应试',m.name+(pass?'榜上有名':'这次没有考中'),text,['银钱 −12 两']);save();render();showDialog(pass?'远处捎来了好消息':'还没有走到这里',`<p class="help">${esc(m.name)}${text}</p>`,`<button class="btn primary" onclick="closeModal();openMember(${id})">看看接下来怎样安排</button>`);}
const PURCHASES={land:{name:'置办一亩田',price:60,desc:'每年额外收粮 4 石；不改变个人主业。'},home:{name:'安置一方小院',price:100,desc:'不再付租金；休养每年额外恢复 1 点体魄。'},workshop:{name:'置办木工作坊',price:140,desc:'有手艺族人经营时，每年额外收入 8 两。'},shop:{name:'置办小商铺',price:200,desc:'有族人经商时，每年额外收入 10 两。'}};
function confirmPurchase(k){if(state.ended)return;const p=PURCHASES[k];showDialog(p.name,`<p class="help">花费 ${p.price} 两。${p.desc}<br>这是本局用实际积蓄购买，不消耗开局点数。</p>`,`<button class="btn" onclick="closeModal()">再看看</button><button class="btn primary" onclick="purchase('${k}')" ${state.money<p.price?'disabled':''}>确认置办 · ${p.price} 两</button>`);}
function purchase(k){const p=PURCHASES[k];if(!p||state.ended||state.money<p.price||(['workshop','shop'].includes(k)&&state[k])||(k==='home'&&['courtyard','estate'].includes(state.home)))return;state.money-=p.price;if(k==='land')state.land++;else if(k==='home')state.home='courtyard';else state[k]=true;record('家业',p.name,p.desc,['银钱 −'+p.price+' 两']);closeModal();save();render();toast('家业已添置，下一年开始计入生活。');}
function buyGrain(){const price=by(ERA,state.era).food*10;if(state.ended||state.money<price)return toast('这次买粮需要 '+price+' 两。');state.money-=price;state.grain+=10;record('买卖','从市集补了十石粮','当前粮价每石 '+by(ERA,state.era).food+' 两。',['银钱 −'+price+' 两','存粮 +10 石']);save();render();}
function sellGrain(){if(state.ended||state.grain<10)return toast('至少留有十石粮，才能按这一份出售。');const money=Math.max(1,by(ERA,state.era).food-1)*10;state.grain-=10;state.money+=money;record('买卖','卖出十石存粮','出售价格比购买价低每石一两，不能往返交易凭空获利。',['银钱 +'+money+' 两','存粮 −10 石']);save();render();}
function openMove(){if(state.ended)return;showDialog('下一处，在哪里安家？',`<div class="notice">搬家花费 30 两。本版以全家共同迁居模拟：保留人、产业账面所有权、主业与信物，并切换地区收支规则；异地支系与实际资产转移尚未细化。</div><div class="candidate-list">${PLACES.filter(p=>p.id!==state.place).map(p=>`<div class="candidate"><div class="between"><span class="candidate-name">${p.name}</span><button class="btn small" onclick="moveTo('${p.id}')" ${state.money<30?'disabled':''}>在这里安家</button></div><p>${p.desc}</p></div>`).join('')}</div>`,`<p>这是本局迁居，不会重新创建家族。</p><button class="btn" onclick="closeModal()">暂时留下</button>`);}
function moveTo(id){if(state.ended||state.money<30||state.place===id||!PLACES.some(p=>p.id===id))return;const from=by(PLACES,state.place);state.money-=30;state.place=id;state.metrics.migrations++;state.metrics.lastMove=state.elapsed;record('迁居','在'+by(PLACES,id).short+'重新落脚','一家人从'+from.short+'迁来。每个人的主业、关系与人生记录都保留了。',['银钱 −30 两']);living().forEach(m=>personRecord(m,'随家族迁居到'+by(PLACES,id).short+'。'));closeModal();save();render();toast('家族已经迁居，时间继续向前。');}
function confirmEnding(id){const e=endingBy(id);if(!e||state.ended||!readyEndings().some(x=>x.id===id))return;showDialog('在「'+e.title+'」这里落笔？',`<p class="help">选择这个主终章，会结束当前这一轮家族人生。之后仍能阅读族人传记与年鉴，但不再推进年份或改变安排。</p><div class="inline-hint">也可以暂不落笔，继续走向其他结局。只收藏这一轮确认的主终章，不把所有达标项一次性记成已通关。</div>`,`<button class="btn" onclick="closeModal()">还想再过些年</button><button class="btn primary" onclick="closeModal();finishRun('${id}')">确认终章，结束本轮</button>`);}
function showConclusion(){if(!state.ended)return;const e=endingBy(state.ended.id),leadNames=state.leaders.map(h=>get(h.id)?.name||'未记载').join('、');showDialog(state.family+'氏 · 本局终章',`<div class="gameover-body" style="padding:10px 7px"><div class="eyebrow">凡世王朝 · 经营 ${state.elapsed} 年</div><h2>${esc(e.title)}</h2><p>${e.epilogue}</p><p>${esc(leadNames)}，先后主持过这个家的事务。那些没有当过族长的人，同样把本事与年月留在这里。</p><div class="gameover-numbers"><div><strong>${Math.max(...state.members.map(m=>m.gen))}</strong><span>代人入谱</span></div><div><strong>${state.leaders.length}</strong><span>任族长</span></div><div><strong>${state.members.length}</strong><span>段人生</span></div></div><p class="small-note" style="font:12px/1.9 var(--sans)">信物解锁与这一轮的主终章已存入本地档案。下一局总分仍为 ${LIMIT}。</p></div>`,`<button class="btn" onclick="closeModal();navigate('history')">再翻翻家族年鉴</button><button class="btn primary" onclick="closeModal();showSetup()">开启另一家的人生</button>`);}
function openDesignEnding(id){const e=ORIGINAL_CATALOG.find(x=>x.id===id);if(!e)return;showDialog(e.title+' · 设定样稿',`<div class="notice">这是保留的设计条目，尚未接入本版判定。不显示虚假的实时进度，也不会在游戏中自动触发。</div><div class="section-label">设想中的条件</div><p class="help">${e.conditions.map(esc).join('；')}。</p><details class="plain-details"><summary>展开终章样稿</summary><p>${esc(e.epilogue)}</p></details>`,`<button class="btn" onclick="closeModal()">先留个念想</button>`);}
function openHelp(){showDialog('先把这一家人的日子过起来',`<div class="help"><h3>开局只有一个总分。</h3><p>总分 100，所有项目独立计价。可以集中投入任一方向，可以剩余分数；不会自动降低你的其他选择。只有超分或关系不成立时，才不能正式开局。</p><h3>先安排，再过一年。</h3><p>从「全体族人」调整主业；未修改的安排会持续。重要家事需要先答复。信物调查同时进行，不会擅自替换主业。出师后也由你决定是否转行。</p><h3>换族长，不换家族。</h3><p>可以主动交接或离世后选任。所有族人的关系、安排与人生记录都保留。暂时没有成年人时，孩子仍会长大。</p><h3>信物是新的可能，不是永久叠加的强化。</h3><p>前三件初始开放，共七件可收藏。带上老木尺，查访并修复旧图，就能解锁营造图。收藏与本局持有物分别记录；下一局仍然只有 100 点。</p><h3>终章由你落笔。</h3><p>13 条演示终章有真实判定。普通终章达标后可以继续玩；确认主终章才结束。全员离世自动结束。其余凡世草案只作预览。</p><h3>这还是原型。</h3><p>年度经济、关系、寿命、婚配、出生与时代变化使用简化规则。没有完整官场、战争、个人独立财产和跨世界迁移。未使用联网模型生成事件，所有故事分支在文件内。</p><h3>存档在这里。</h3><p>V4 使用独立本地存档，不修改 V1/V2/V3。浏览器、隐私设置或文件路径变化可能影响本地存储；可以导出 JSON，在 V4 中导入 V3 或 V4 存档。没有账号和云同步。</p><div class="row button-row-wrap" style="margin-top:18px"><button class="btn small" onclick="exportSave()">导出存档</button><button class="btn small" onclick="document.getElementById('import-save').click()">导入 V3 / V4 存档</button></div></div>`,`<p data-save></p><button class="btn primary" onclick="closeModal()">开始看看</button>`);updateStorageNote();}
function exportSave(){save();const blob=new Blob([JSON.stringify(store,null,2)],{type:'application/json;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='家业-V4-存档.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500);toast('已导出当前开局草案、家族进度与信物解锁。');}
function isValidImport(s){if(!s||s.schema!==3||!s.draft||!s.profile||!Array.isArray(s.profile.unlocked)||!Array.isArray(s.profile.records)||!Array.isArray(s.profile.endings))return false;if(s.profile.unlocked.some(id=>!RELICS.some(r=>r.id===id)))return false;
 const d=s.draft;if(!Array.isArray(d.members)||!d.members.length||d.members.length>300||!Array.isArray(d.relics)||typeof d.family!=='string'||d.family.length>6)return false;
 for(const [field,arr] of [['era',ERA],['place',PLACES],['origin',ORIGINS],['habit',HABITS],['tie',TIES],['home',HOMES]])if(!arr.some(x=>x.id===d[field]))return false;
 const memberSafe=m=>Number.isInteger(m.id)&&m.id>0&&Number.isInteger(m.age)&&m.age>=0&&m.age<200&&typeof m.name==='string'&&m.name.length<=32&&Array.isArray(m.parents)&&m.parents.every(Number.isInteger)&&Number.isInteger(m.talent)&&m.talent>=1&&m.talent<=5&&FOCUSES[m.focus]!=null&&EXPERIENCES.some(e=>e.id===m.experience)&&JOBS[m.job];if(d.members.some(m=>!memberSafe(m)))return false;
 const g=s.game;if(g){if(g.version!==3||!Array.isArray(g.members)||g.members.some(m=>!memberSafe(m)||!Array.isArray(m.bio)||!m.jobYears)||!Array.isArray(g.logs)||!Array.isArray(g.events)||!Array.isArray(g.relics)||!g.metrics||!g.flags||!g.config||!Number.isInteger(g.elapsed)||!Number.isFinite(g.money)||!Number.isFinite(g.grain)||typeof g.family!=='string')return false;if(g.events.some(e=>typeof e.id!=='string'||!/^[a-zA-Z0-9_-]+$/.test(e.id)))return false;if(g.relics.some(r=>!RELICS.some(d=>d.id===r.id)||!Array.isArray(r.history)))return false;if(g.ended&&!endingBy(g.ended.id))return false;}return true;}
async function readImport(input){const file=input.files?.[0];input.value='';if(!file)return;if(file.size>15_000_000)return toast('存档文件过大，请使用本版导出的 JSON。');try{const s=JSON.parse(await file.text());if(!isValidImport(s))throw new Error('invalid');pendingImport=s;showDialog('导入这一份家业存档？','<p class="help">会替换本浏览器当前的 V4 草案、家族和收藏记录。不会影响原 V1/V2/V3 文件的存档。建议先导出现有进度。</p>','<button class="btn" onclick="exportSave()">先导出现有存档</button><button class="btn primary" onclick="commitImport()">确认替换</button>');}catch(e){toast('没有读到有效的 V3 / V4 存档，当前进度没有改动。');}}
function commitImport(){if(!pendingImport)return;const previous=store;try{store=pendingImport;draft=store.draft;state=store.game;screen=state?'game':'setup';page='overview';step=0;activeEventChoice=null;closeModal();render();save();pendingImport=null;toast('存档已导入。');}catch(e){store=previous;draft=store.draft;state=store.game;screen=state?'game':'setup';render();toast('导入内容不完整，已保留原来的进度。');}}

/* Creation V4: one total cap, page-local headroom, coherent historical starts. */
const OPENING_PERIODS = [
  {id:'rebuild',name:'乱后重建',era:'rebuild',from:1,to:36,years:[12,24,36],defaultYear:24},
  {id:'peace',name:'安定盛年',era:'peace',from:37,to:84,years:[48,60,72],defaultYear:72},
  {id:'strain',name:'盛世渐晚',era:'strain',from:85,to:120,years:[96,108,120],defaultYear:108},
  {id:'unrest',name:'变局将至',era:'unrest',from:121,to:160,years:[132,144,156],defaultYear:144}
];
const PAGE_KEYS = [
  ['era','calendar','openingId','place','origin'],
  ['members','leader','nextId'],
  ['money','grain','land','home','workshop','shop','habit','tie'],
  ['relics']
];
let changedPreview = new Set(), pageRandomUndo = {}, allRandomUndo = null;
let setupScrollBefore = 0, sideDetailsOpen = false, treeDetailsOpen = false;
let migratedOpening = false;
function openingPeriod(d=draft){return OPENING_PERIODS.find(p=>p.id===d.openingId)||OPENING_PERIODS.find(p=>p.era===d.era)||OPENING_PERIODS[1];}
function normalizeOpening(d){
  const p=openingPeriod(d), old={era:d.era,calendar:d.calendar,openingId:d.openingId};
  d.openingId=p.id;d.era=p.era;
  if(!p.years.includes(d.calendar))d.calendar=p.defaultYear;
  return old.era!==d.era||old.calendar!==d.calendar;
}
migratedOpening=normalizeOpening(draft);store.uiVersion=4;
function pageBudget(index=step,d=draft){
  const groups=pointGroups(d),total=round(groups.reduce((n,g)=>n+g.value,0));
  if(index===4)return {used:total,other:0,capacity:LIMIT,remaining:round(LIMIT-total),total,review:true};
  const used=round(groups.filter(g=>g.step===index).reduce((n,g)=>n+g.value,0));
  const other=round(total-used),capacity=round(LIMIT-other);
  return {used,other,capacity,remaining:round(capacity-used),total,review:false};
}
function snapshotPage(index,d=draft){return Object.fromEntries(PAGE_KEYS[index].map(k=>[k,clone(d[k])]));}
function applyPage(index,snapshot){for(const k of PAGE_KEYS[index])draft[k]=clone(snapshot[k]);}
function markChanged(...keys){changedPreview=new Set(keys);}
function choicePage(k){return k==='family'?0:PAGE_KEYS.findIndex(keys=>keys.includes(k));}
function invalidatePageUndo(index){delete pageRandomUndo[index];allRandomUndo=null;}
function sectionKeysForPage(index){return [['time','origin','place'],['members','leader'],['assets','habit','tie'],['relics']][index]||[];}
function previewKeyForField(k){return ['era','calendar','openingId'].includes(k)?'time':['money','grain','land','home','shop','workshop'].includes(k)?'assets':k;}
function safeDraftEstimate(d=draft){try{const tmp=clone(d);if(!tmp.members.some(m=>m.id===tmp.leader))tmp.leader=tmp.members.find(m=>m.age>=18)?.id||tmp.members[0]?.id;if(!tmp.members.length)return null;return estimate(makeGame(tmp));}catch(e){return null;}}
function previewPart(key,label,html,index){
  return `<div class="preview-block ${changedPreview.has(key)?'preview-flash':''}" data-preview-key="${key}"><div class="preview-label"><span>${esc(label)}</span>${changedPreview.has(key)?'<span class="preview-update">已更新</span>':`<button class="preview-jump" onclick="goStep(${index})" aria-label="修改${esc(label)}">修改 ↗</button>`}</div>${html}</div>`;
}
function previewChip(text,accent=false){return `<span class="preview-chip ${accent?'chosen':''}">${esc(text)}</span>`;}
function renderFamilyPreview(d=draft,liveEdit=false){
  const lead=d.members.find(m=>m.id===d.leader),b=safeDraftEstimate(d);
  const gen=d.members.length?Math.max(...d.members.map(m=>generation(m,d.members))):0;
  const memberRows=d.members.map(m=>`<div class="preview-member" data-preview-person="${m.id}"><strong>${esc(m.name)}${m.id===d.leader?tag('族长','red'):''}</strong><span>${m.age}岁 · ${TALENTS[m.talent-1]?.name||'待选'}</span><small>${esc(by(EXPERIENCES,m.experience).name)} · ${esc(FOCUSES[m.focus]||'尚无偏向')}<br>${esc(JOBS[m.job]?.name||'待安排')} · ${esc(m.trait)}<br>${esc(draftRelationFor(m,d))}</small></div>`).join('');
  return `<section class="family-preview" id="family-preview"><div class="preview-top"><span class="muted">这本家谱的第一页</span><span class="tag green">${liveEdit?'编辑预览':'随选择更新'}</span></div><h3 data-preview-key="family" class="${changedPreview.has('family')?'preview-flash':''}">${esc(d.family||'未名')}氏家族</h3>
    ${previewPart('time','开局时间与时世',`<div class="preview-values">${previewChip('大晟历 '+d.calendar+' 年',true)}${previewChip(by(ERA,d.era).name)}</div>`,0)}
    ${previewPart('origin','家族来历',`<div class="preview-values">${previewChip(by(ORIGINS,d.origin).name,true)}</div>`,0)}
    ${previewPart('place','落脚之地',`<div class="preview-values">${previewChip(by(PLACES,d.place).name+' · '+by(PLACES,d.place).short)}</div>`,0)}
    ${previewPart('leader','首任族长',`<p>${lead?esc(lead.name)+' · '+lead.age+'岁 · '+esc(JOBS[lead.job]?.name||'待安排'):'尚未指定成年成员'}</p>`,1)}
    ${previewPart('members','家中这些人',`<div class="preview-values">${previewChip(d.members.length+'人 · '+gen+'代')}${previewChip(d.members.filter(m=>m.age>=18).length+'位成年 / '+d.members.filter(m=>m.age<18).length+'位孩子')}</div><p style="margin-top:5px">${d.members.map(m=>esc(m.name)).join('、')||'还没有成员'}</p><details class="preview-tree" ${treeDetailsOpen?'open':''} ontoggle="treeDetailsOpen=this.open"><summary>展开每个人的安排与关系</summary>${memberRows}</details>`,1)}
    ${previewPart('assets','家底与产业',`<div class="preview-values">${previewChip(d.money+'两现银')}${previewChip(d.grain+'石存粮')}${previewChip(d.land+'亩田')}${previewChip(by(HOMES,d.home).name)}${d.workshop?previewChip('木工作坊',true):''}${d.shop?previewChip('小商铺',true):''}</div>`,2)}
    ${previewPart('habit','家风',`<div class="preview-values">${previewChip(by(HABITS,d.habit).name)}</div>`,2)}
    ${previewPart('tie','往来关系',`<div class="preview-values">${previewChip(by(TIES,d.tie).name)}</div>`,2)}
    ${previewPart('relics','带入的信物',`<div class="preview-values">${d.relics.map(id=>previewChip(relicDef(id).name,true)).join('')||'<span class="preview-none">不带信物，从这里写起。</span>'}</div>`,3)}
    <div class="preview-estimate"><span>首年银钱预计结余</span><strong class="${(b?.money||0)<0?'negative':'positive'}">${b?signed(b.money)+' 两':'完善安排后显示'}</strong></div>${liveEdit?'<p class="small-note" style="margin-top:8px">这是尚未保存的成员预览；取消会恢复。</p>':''}
  </section>`;
}
function draftRelationFor(m,d){const ps=m.parents.map(id=>d.members.find(x=>x.id===id)?.name).filter(Boolean),sp=d.members.find(x=>x.id===m.spouse);return [ps.length?'父母／养亲：'+ps.join('、'):'未设上代',sp?'配偶：'+sp.name:''].filter(Boolean).join('；');}
renderBudget=function(d=draft,liveEdit=false){
  const p=pageBudget(step,d),over=p.total>LIMIT,cap=Math.max(0,p.capacity),usedText=p.review?'本局已用':'本页已用',capText=p.review?'总分上限':'本页可分配';
  return `<section class="budget-panel ${over?'budget-over':''}"><div class="budget-top"><span>${p.review?'落笔前核对':STEP_NAMES[step][0]+' · 点数'}</span>${tag(over?'暂不能开局':p.review?'总分核对':'按页分配',over?'red':'outline')}</div><div class="budget-number" data-page-budget-used="${p.used}" data-page-budget-capacity="${p.capacity}">${p.used}<small>/ ${cap}</small></div><div class="budget-sub-label">${usedText} / ${capText}</div><div class="budget-track"><span style="width:${cap?clamp(p.used/cap*100,0,100):p.used?100:0}%"></span></div><div class="budget-caption">${p.review?'确认所有选择后，再开始这一家人的生活。':`其他页已用 <strong>${p.other}</strong> 点，留给本页 <strong>${cap}</strong> 点。<br>${p.remaining>=0?'本页还可投入 <strong>'+p.remaining+'</strong> 点。':'当前总分超出 <strong>'+round(-p.remaining)+'</strong> 点。'}`}</div><div class="budget-total-line"><span>总分仍为 ${LIMIT}，不设固定配额</span><strong data-total-points="${p.total}">${p.total}/${LIMIT}</strong></div>${over?`<div class="budget-alert" role="status">已超出 ${round(p.total-LIMIT)} 点，不能开始游戏。<br>${p.capacity<0?'其他页已用尽总分，请返回调整。':'可以继续修改，由你决定减少哪一项。'}</div>`:''}<details class="budget-details" ${sideDetailsOpen?'open':''} ontoggle="sideDetailsOpen=this.open"><summary>查看各页用分与计算方法</summary><div class="budget-rows">${STEP_NAMES.slice(0,4).map((s,i)=>`<div class="budget-page-row ${i===step?'active':''}"><button onclick="goStep(${i})">0${i+1} ${s[0]}</button><span>${pageBudget(i,d).used} 点</span></div>`).join('')}</div><div class="budget-rule">本页可分配 = ${LIMIT} − 其他页已用。<br>回到前页调整，后页额度也会随之变化。<br><button class="text-btn" onclick="openPriceDetail()">逐项分数明细 ↗</button></div></details></section>${renderFamilyPreview(d,liveEdit)}`;
};
function pageTools(){
 const undo=step<4?pageRandomUndo[step]:allRandomUndo;
 return `<div class="setup-page-actions"><div class="eyebrow">凡世王朝 · 开篇 ${String(step+1).padStart(2,'0')} / 05</div><div class="random-actions">${undo?`<button class="text-btn random-undo" onclick="${step<4?'undoPageRandom()':'undoAllRandom()'}">撤销${step<4?'本页':'整局'}随机</button>`:''}<button class="btn random-button" data-random-page="${step}" onclick="${step<4?'randomizePage()':'askRandomAll()'}"><span class="random-icon" aria-hidden="true">↻</span>${step<4?'随机本页':'随机整个开局'}</button></div></div>`;
}
function pageRandomHint(){return ['只随机本页的时期、来历与地区；不改家族姓氏或其他页。','只随机本页的家人、亲属关系、资质与族长；不改其他页。','只随机本页的家底、住宅、家风与人情；不改其他页。','只从已经解锁的信物中随机选择；不会调整其他页。','本页只核对，不另占点数；随机整局会先请你确认。'][step];}
setupView=function(){return `${worldHeader('setup')}<div class="v3-setup"><aside class="setup-left"><div class="nav-kicker">创建一个家族</div>${STEP_NAMES.map((s,i)=>`<button class="step-link ${step===i?'active':''}" onclick="goStep(${i})" ${step===i?'aria-current="step"':''}><span>0${i+1}</span><div>${s[0]}<small>${s[1]}</small><span class="step-cost">${i<4?'已选 '+pageBudget(i).used+' 点':'不额外计分'}</span></div></button>`).join('')}<blockquote>每一页留多少，<br>每一项选什么，<br>都由你作主。</blockquote></aside><main class="v3-center" id="setup-content">${pageTools()}<p class="page-random-note">${pageRandomHint()}</p>${[setupWorld,setupPeople,setupAssets,setupRelics,setupReview][step]()}</main><aside class="budget-side" id="budget-side" aria-label="本页点数与实时家谱">${renderBudget()}</aside></div>${setupFooter()}`;};
setupWorld=function(){const p=openingPeriod(),e=by(ERA,draft.era);return `<h1 class="page-title">这一家，从哪一年开始？</h1><p class="intro-copy">时间决定起始时世。选好同一段历史，再决定这个家的来处与落脚之地。</p><div class="world-ribbon"><div><strong>凡世王朝 · 大晟</strong><p>普通人的一生，与几代人的家业。无修炼、无超自然延寿。</p></div><button class="text-btn" onclick="showWorld()">了解这个世界 ↗</button></div><label class="field" style="max-width:230px">家族姓氏 · 不计分<input id="family-name" maxlength="6" value="${esc(draft.family)}" oninput="setFamilyName(this.value)" placeholder="例如：林、沈、司徒"></label><div class="time-heading"><h2>选择开局时期</h2><span>时期与时世是一项，只计一次分</span></div><div class="option-grid" id="opening-periods">${OPENING_PERIODS.map(period=>{const era=by(ERA,period.era),selected=p.id===period.id;return `<button class="option-card epoch-card ${selected?'chosen':''}" onclick="setOpeningPeriod('${period.id}')" aria-pressed="${selected}" data-opening-period="${period.id}"><div class="between"><strong>${period.name}</strong><span class="cost-selected"><span class="price">${era.cost} 点</span><span class="select-dot">✓</span></span></div><div class="epoch-range">大晟历 ${period.from}—${period.to} 年</div><p>起始时世：<span class="epoch-era">${era.name}</span></p><div class="option-effect">${era.effect}</div></button>`}).join('')}</div><div class="time-select-row"><label class="field">在这一时期的哪年开局<select id="calendar-year" aria-label="选择开局年份" onchange="setOpeningYear(this.value)">${p.years.map(y=>`<option value="${y}" ${draft.calendar===y?'selected':''}>大晟历 ${y} 年${y===p.years[0]?' · 前段':y===p.years.at(-1)?' · 后段':' · 中段'}</option>`).join('')}</select><small>选择年份不重复收费。</small></label><div class="time-derived"><span>由所选时间确定 · 不再独立选择</span><strong id="derived-era">${e.name}</strong><small>这一局从经营第 1 年开始。</small></div></div><p class="time-note">以上是同一条开局历史，不会出现“乱世年份＋承平时世”。进入游戏后，时世按本局事件演变，家族经营年数单独累计。</p>${sectionTitle('这个家的来处','只包含写明的效果，不附送人口与家财')}${optionCards('origin',ORIGINS,'origin-grid')}${sectionTitle('在哪一处落脚','不改动家人或家底')}${optionCards('place',PLACES)}<div class="inline-hint">寒门也可以有钱，名门也可以只剩几个人。你分配的是起点，不是被规定好的结局。</div>`;};
setupFooter=function(){const b=pageBudget(),over=b.total>LIMIT,errors=step===4?validateDraft():[];
 return `<footer class="create-footer" id="create-footer"><div class="points-footer"><strong class="${over?'negative':''}">${b.used}<small> / ${Math.max(0,b.capacity)}</small></strong><p>${step===4?'本局总分 / 上限':'本页已用 / 可分配'}<br>${over?'超出 '+round(b.total-LIMIT)+' 点 · 不能开局':step===4?'检查通过后，即可开始':'还可投入 '+b.remaining+' 点'}<br><button class="mobile-live-toggle" onclick="openLivePreview()">查看实时家谱 ↗</button></p></div><span class="footer-hint">${over?'已保留你的选择，调整到总分以内才能开局。':step===4?'确认的是开局，后代的路仍由你来走。':'其他页已用 '+b.other+' 点 · 总计 '+b.total+'/'+LIMIT}</span><div class="row">${step?`<button class="btn" onclick="goStep(${step-1})">上一步</button>`:''}${step<4?`<button class="btn primary" onclick="goStep(${step+1})">${['安排家中这些人','安排安身家底','挑选家传旧物','看看这一家'][step]} →</button>`:`<button id="start-game" class="btn primary" onclick="startGame()" ${over||errors.length?'disabled aria-disabled="true"':'aria-disabled="false"'}>${over?'超出 '+round(b.total-LIMIT)+' 点，暂不能开始':errors.length?'完善开局后再开始':'立下家谱，开始 →'}</button>`}</div></footer>`;
};
function openLivePreview(){showDialog('此刻的家谱草案',renderBudget(),'<button class="btn primary" onclick="closeModal()">继续选择</button>');}
const v3ValidateDraft=validateDraft;
validateDraft=function(d=draft){const errors=v3ValidateDraft(d),p=OPENING_PERIODS.find(x=>x.id===d.openingId);if(!p||!p.years.includes(d.calendar)||p.era!==d.era)errors.push('请从同一开局时期选择年份；时世由时间决定。');if(!Number.isFinite(totalPoints(d)))errors.push('点数必须是有效数值，请检查各页。');return [...new Set(errors)];};
function rerenderSetup(){const scroll=window.scrollY,side=$('#budget-side')?.scrollTop||0;save();render();window.scrollTo(0,scroll);if($('#budget-side'))$('#budget-side').scrollTop=side;}
setChoice=function(k,id){if(k==='era')return setOpeningPeriod(id);const allowed={origin:ORIGINS,place:PLACES,habit:HABITS,tie:TIES,home:HOMES};if(!allowed[k]?.some(x=>x.id===id))return;draft[k]=id;invalidatePageUndo(choicePage(k));markChanged(previewKeyForField(k));rerenderSetup();};
function setOpeningPeriod(id){const p=OPENING_PERIODS.find(x=>x.id===id);if(!p)return;draft.openingId=p.id;draft.calendar=p.defaultYear;draft.era=p.era;invalidatePageUndo(0);markChanged('time');rerenderSetup();}
function setOpeningYear(y){const p=openingPeriod(),year=Number(y);if(!p.years.includes(year))return;draft.calendar=year;draft.era=p.era;draft.openingId=p.id;invalidatePageUndo(0);markChanged('time');rerenderSetup();}
setToggle=function(k){if(!['workshop','shop'].includes(k))return;draft[k]=!draft[k];invalidatePageUndo(2);markChanged('assets');rerenderSetup();};
setFamilyName=function(v){draft.family=v.slice(0,6);markChanged('family');refreshSetupBits();};
setNumber=function(k,v,inc,min,max){if(k==='calendar')return setOpeningYear(v);const n=Number(v);if(!Number.isFinite(n)||!['money','grain','land'].includes(k))return;draft[k]=clamp(Math.round(n/inc)*inc,min,max);invalidatePageUndo(2);markChanged('assets');rerenderSetup();};
changeResource=function(k,delta){if(!['money','grain','land'].includes(k))return;draft[k]=Math.max(0,draft[k]+delta);invalidatePageUndo(2);markChanged('assets');rerenderSetup();};
draftLeader=function(id){const m=draft.members.find(x=>x.id===id);if(!m||m.age<18)return;draft.leader=id;invalidatePageUndo(1);markChanged('leader','members');rerenderSetup();toast(m.name+'已标记为首任族长。');};
toggleRelic=function(id){if(!store.profile.unlocked.includes(id))return;draft.relics=draft.relics.includes(id)?draft.relics.filter(x=>x!==id):[...draft.relics,id];invalidatePageUndo(3);markChanged('relics');rerenderSetup();};
refreshSetupBits=function(){const e=$('#budget-side'),scroll=e?.scrollTop||0;if(e){e.innerHTML=renderBudget();e.scrollTop=scroll;}const f=$('#create-footer');if(f)f.outerHTML=setupFooter();save();};
const v3GoStep=goStep;goStep=function(n){markChanged();v3GoStep(n);};
const v3SaveDraftPerson=saveDraftPerson;
saveDraftPerson=function(isNew){const before=JSON.stringify(draft.members);markChanged('members','leader');v3SaveDraftPerson(isNew);if(before!==JSON.stringify(draft.members))invalidatePageUndo(1);};
const v3RemoveDraft=commitRemoveDraft;
commitRemoveDraft=function(id){markChanged('members','leader');invalidatePageUndo(1);v3RemoveDraft(id);};
const v3EstimatePerson=draftPersonEstimate;
draftPersonEstimate=function(){v3EstimatePerson();if(!$('#dp-name'))return;const edit=draftPersonValues(),candidate=clone(draft),i=candidate.members.findIndex(m=>m.id===edit.id);if(i>=0)candidate.members[i]=edit;else candidate.members.push(edit);const b=pageBudget(1,candidate);$('#dp-total-note').textContent=`保存后本页 ${b.used} / ${Math.max(0,b.capacity)} 点${b.total>LIMIT?'，总分超出 '+round(b.total-LIMIT)+' 点，不能开局':'；其他页不变'}。`;
 const side=$('#budget-side');if(side){const top=side.scrollTop;markChanged('members','leader');side.innerHTML=renderBudget(candidate,true);side.scrollTop=top;}
};
const v3PersonDialog=draftPersonDialog;
draftPersonDialog=function(isNew){v3PersonDialog(isNew);document.querySelectorAll('#modal-root input,#modal-root select').forEach(el=>{if(el.id.startsWith('dp-')&&!['dp-age','dp-talent','dp-experience'].includes(el.id))el.addEventListener(el.tagName==='SELECT'?'change':'input',draftPersonEstimate);});};
const v3CloseModal=closeModal;
closeModal=function(){const editing=!!$('#dp-name');v3CloseModal();if(editing&&screen==='setup'){markChanged();refreshSetupBits();}};
/* Random choices are page-local and constrained by the remaining shared total. */
function pickRandom(arr){return arr[Math.floor(Math.random()*arr.length)];}
function randInt(min,max){return min+Math.floor(Math.random()*(max-min+1));}
function shuffled(arr){return arr.map(v=>({v,k:Math.random()})).sort((a,b)=>a.k-b.k).map(x=>x.v);}
function randomWorld(cap){const choices=[];for(const p of OPENING_PERIODS)for(const place of PLACES)for(const origin of ORIGINS){if(by(ERA,p.era).cost+place.cost+origin.cost<=cap)choices.push({era:p.era,openingId:p.id,calendar:pickRandom(p.years),place:place.id,origin:origin.id});}return choices.length?pickRandom(choices):null;}
function randomPeople(cap,base){
 if(cap<6)return null;const names=shuffled(['知秋','怀宁','云舒','景和','清和','予安','望舒','明川','知禾','景宁','行舟','疏桐','静微','成蹊','若衡','知远']);
 let shape=pickRandom(['solo','couple','children','siblings','three']);if(cap<16)shape='solo';
 const ms=[],plain=(id,age,o={})=>rawPerson({id,name:base.family+names[id-1],age,talent:1,experience:'none',job:age<5?'play':age<18?'study':'farm',trait:pickRandom(['踏实','细致','仁厚','好奇','开朗','沉静']),...o});
 const oldest=cap<8?randInt(56,72):shape==='three'?randInt(62,72):randInt(37,51);
 ms.push(plain(1,oldest,{sex:pickRandom(['男','女'])}));
 if(shape==='couple'||shape==='children'){ms[0].spouse=2;ms.push(plain(2,oldest-randInt(0,3),{spouse:1,sex:ms[0].sex==='男'?'女':'男',name:pickRandom(['许','周','沈','何','陆'])+names[1]}));}
 if(shape==='children'){
  const maxKids=Math.min(5,Math.floor((cap-16)/4)),kids=randInt(1,Math.max(1,maxKids));
  for(let j=0;j<kids;j++)ms.push(plain(ms.length+1,randInt(1,16),{parents:[1,2],sex:pickRandom(['男','女'])}));
 }
 if(shape==='siblings'){
  const count=randInt(2,Math.min(6,Math.floor(cap/8)));
  for(let j=1;j<count;j++)ms.push(plain(j+1,oldest-j*2,{sex:pickRandom(['男','女'])}));
 }
 if(shape==='three'){
  if(cap>=18){const childAge=randInt(32,oldest-20);ms.push(plain(2,childAge,{parents:[1],sex:pickRandom(['男','女'])}));ms.push(plain(3,randInt(5,Math.min(16,childAge-18)),{parents:[2],sex:pickRandom(['男','女'])}));}
 }
 let cost=ms.reduce((n,m)=>n+personBase(m.age),0);if(cost>cap)return randomPeople(Math.min(cap,15),base);
 for(const m of shuffled(ms)){
  const talentChoices=TALENTS.map((t,i)=>({i:i+1,cost:t.cost})).filter(t=>t.cost<=cap-cost);const t=pickRandom(talentChoices);m.talent=t.i;cost+=t.cost;
  const xp=EXPERIENCES.filter(x=>x.cost<=cap-cost&&(m.age>=18||x.id==='none'||(m.age>=8&&x.id==='basic')));const ex=pickRandom(xp);m.experience=ex.id;cost+=ex.cost;
  m.focus=pickRandom(Object.keys(FOCUSES));
  const jobs=Object.keys(JOBS).filter(k=>candidateHasJob(m,k));m.job=pickRandom(jobs);if(m.age<5)m.job='play';
 }
 return {members:ms,leader:pickRandom(ms.filter(m=>m.age>=18)).id,nextId:ms.length+1};
}
function randomAssets(cap){if(cap<0)return null;const r={money:0,grain:0,land:0,home:'rented',workshop:false,shop:false,habit:'none',tie:'none'};let spent=0;
 const fields=shuffled(['home','habit','tie','workshop','shop','money','grain','land']);
 for(const key of fields){const room=Math.floor(cap-spent);if(['home','habit','tie'].includes(key)){const arr=key==='home'?HOMES:key==='habit'?HABITS:TIES;const val=pickRandom(arr.filter(x=>x.cost<=room));r[key]=val.id;spent+=val.cost;}
  else if(key==='workshop'||key==='shop'){const cost=key==='workshop'?14:20;if(room>=cost&&Math.random()<.35){r[key]=true;spent+=cost;}}
  else {const unit=key==='land'?4:1,scale=key==='money'?10:key==='grain'?4:1;const max=Math.floor(room/unit);const count=randInt(0,Math.min(max,key==='money'?25:key==='grain'?14:5));r[key]=count*scale;spent+=count*unit;}}
 return r;
}
function randomRelics(cap){const list=RELICS.filter(r=>store.profile.unlocked.includes(r.id));const combos=[];for(let mask=0;mask<2**list.length;mask++){const rs=list.filter((_,i)=>mask&(1<<i));if(rs.reduce((n,r)=>n+r.cost,0)<=cap)combos.push({relics:rs.map(r=>r.id)});}return combos.length?pickRandom(combos):null;}
function generatePage(index,cap,d){return [()=>randomWorld(cap),()=>randomPeople(cap,d),()=>randomAssets(cap),()=>randomRelics(cap)][index]();}
function randomizePage(){if(step>3)return askRandomAll();const index=step,b=pageBudget(index);if(b.capacity<0)return toast('其他页已超出总分 '+round(-b.capacity)+' 点。本页随机不会改动其他页，请先调整。');
 const before=snapshotPage(index),serial=JSON.stringify(before);let result=null;
 for(let n=0;n<100;n++){const candidate=generatePage(index,b.capacity,draft);if(candidate&&JSON.stringify(candidate)!==serial){const d={...clone(draft),...candidate};if(totalPoints(d)<=LIMIT&&Number.isFinite(totalPoints(d))){result=candidate;break;}}}
 if(!result)return toast(index===1&&b.capacity<6?'本页至少需要 6 点，才能安排一位成年族长。请先从其他页留出点数。':'当前额度下没有其他可选组合，已保留你的选择。');
 pageRandomUndo[index]=before;allRandomUndo=null;applyPage(index,result);markChanged(...sectionKeysForPage(index));rerenderSetup();toast('只随机了「'+STEP_NAMES[index][0]+'」，本页使用 '+pageBudget(index).used+' / '+Math.max(0,b.capacity)+' 点。其他页未变。');
}
function undoPageRandom(){if(!pageRandomUndo[step])return;applyPage(step,pageRandomUndo[step]);delete pageRandomUndo[step];markChanged(...sectionKeysForPage(step));rerenderSetup();toast('已恢复本页随机前的选择。'+(totalPoints()>LIMIT?'当前总分超出，请调整后再开始。':'其他页未变。'));}
function askRandomAll(){showDialog('重新随机整个开局？','<p class="help">确认页没有新的可选项目。这里会重新选择前四页的时期、来历、家人、家底与已解锁信物，并保留家族姓氏。<br><br>结果会在 100 点以内；不会影响已开始的家族或信物解锁。你也可以撤销这次随机。</p>','<button class="btn" onclick="closeModal()">保留当前选择</button><button class="btn primary" onclick="randomizeAll()">确认随机整局</button>');}
function randomizeAll(){const before=clone(draft);let chosen=null;
 for(let attempt=0;attempt<120;attempt++){
  const d=clone(draft);Object.assign(d,{era:'unrest',openingId:'unrest',calendar:144,place:'village',origin:'plain',money:0,grain:0,land:0,home:'rented',workshop:false,shop:false,habit:'none',tie:'none',relics:[],members:[rawPerson({id:1,name:d.family+'知远',age:62,talent:1,experience:'none',job:'farm'})],leader:1,nextId:2});
  for(const index of shuffled([0,1,2,3])){const cap=pageBudget(index,d).capacity,result=generatePage(index,cap,d);if(result)Object.assign(d,result);}
  if(totalPoints(d)<=LIMIT&&!validateDraft(d).length&&JSON.stringify(d)!==JSON.stringify(before)){chosen=d;break;}
 }
 if(!chosen){closeModal();return toast('这次未组合出有效开局，原来的草案没有改动。');}
 allRandomUndo=before;pageRandomUndo={};draft=chosen;markChanged('time','origin','place','leader','members','assets','habit','tie','relics');closeModal();rerenderSetup();toast('新的组合用了 '+totalPoints()+' / '+LIMIT+' 点。逐页检查后再开始。');
}
function undoAllRandom(){if(!allRandomUndo)return;draft=clone(allRandomUndo);allRandomUndo=null;pageRandomUndo={};markChanged('time','origin','place','leader','members','assets','habit','tie','relics');rerenderSetup();toast('已恢复整局随机前的草案。');}
/* Re-check at both entry points, including direct invocation of the final confirmation. */
const v3StartGame=startGame,v3CommitStart=commitStart;
startGame=function(){if(totalPoints()>LIMIT||!Number.isFinite(totalPoints())){step=4;screen='setup';closeModal();render();toast('总分超出，不能开始。请调整到 '+LIMIT+' 点以内。');return false;}return v3StartGame();};
commitStart=function(){if(totalPoints()>LIMIT||!Number.isFinite(totalPoints())||validateDraft().length){step=4;screen='setup';closeModal();render();toast(validateDraft()[0]||'请先完成开局配置。');return false;}return v3CommitStart();};
/* Keep gameplay and profile data compatible with V3; normalize only an imported draft. */
const v3CommitImport=commitImport;
commitImport=function(){if(pendingImport){pendingImport=clone(pendingImport);const changed=normalizeOpening(pendingImport.draft);pendingImport.uiVersion=4;v3CommitImport();pageRandomUndo={};allRandomUndo=null;if(changed)toast('存档已导入。开局草案已匹配到对应时期的可选年份，已开始的家族时间未改动。');} };
const v3SetupReview=setupReview;
setupReview=function(){return v3SetupReview().replace('全部开局项目合计','前四页选择合计 · 本页不另计分');};
const v3Help=openHelp;
openHelp=function(){v3Help();const body=$('#modal-root .dialog-body');if(body)body.insertAdjacentHTML('afterbegin','<div class="notice"><strong>这次的创建界面</strong><br>时间用选项选择，时世由时间推导，不重复计分。每页显示已用／可分配，其他页调整后会重新计算。随机本页只改本页，遵守剩余额度，可以撤销。确认页随机整局需再次确认。超出总分时，按钮和开局逻辑都禁止开始。</div>');};
/* Bring the just-changed record into view without scrolling the choice page. */
function revealPreviewChange(){
 if(window.innerWidth<=700)return;
 const panel=$('#budget-side .family-preview');if(!panel)return;
 const keys=[...changedPreview];if(!keys.length)return;
 const el=panel.querySelector('[data-preview-key="'+keys.at(-1)+'"]');if(!el)return;
 const a=panel.getBoundingClientRect(),b=el.getBoundingClientRect();
 if(b.bottom>a.bottom-14)panel.scrollTop+=b.bottom-a.bottom+18;
 else if(b.top<a.top+12)panel.scrollTop-=a.top-b.top+12;
}
const v4RerenderSetup=rerenderSetup;
rerenderSetup=function(){v4RerenderSetup();revealPreviewChange();};
const v4SavePerson=saveDraftPerson;
saveDraftPerson=function(isNew){const before=JSON.stringify(draft.members);v4SavePerson(isNew);if(before!==JSON.stringify(draft.members)){markChanged('members','leader');refreshSetupBits();revealPreviewChange();}};
const v4FamilyName=setFamilyName;
setFamilyName=function(v){allRandomUndo=null;v4FamilyName(v);};

render();save();
